sp_widget.client_script:
api.controller = function($scope, spUtil) {

    var c = this;


    /* ============================================================
       BASIC VARIABLES
       ============================================================ */

    c.searchText = '';
    c.statusFilter = '';
    c.branchFilter = '';

    c.filteredDrives = [];

    c.selectedDrive = null;

    c.showDriveModal = false;
    c.showApplyModal = false;
    c.showDriveForm = false;

    c.editingDrive = false;

    c.applyDriveData = null;

    c.savingDrive = false;
    c.applying = false;


    /* ============================================================
       ROLES
       ============================================================ */

    c.isPlacementAdmin =
        c.data.is_placement_admin === true;

    c.isPlacementOfficer =
        c.data.is_placement_officer === true;

    c.isInterviewer =
        c.data.is_interviewer === true;

    c.isStudent =
        c.data.is_student === true;


    /* ============================================================
       DEBUG
       ============================================================ */

    c.debugInterviewer =
        c.data.debug_interviewer || {};

    c.debugStudent =
        c.data.debug_student || {};


    /* ============================================================
       ADD DRIVE BUTTON
       ============================================================ */

    c.showAddDriveButton = function() {

        return (
            c.isPlacementAdmin ||
            c.isInterviewer
        );
    };


    /* ============================================================
       VIEW PERMISSION
       ============================================================ */

    c.canViewDrive = function(drive) {

        return (
            drive &&
            drive.can_view === true
        );
    };


    /* ============================================================
       EDIT PERMISSION
       ============================================================ */

    c.canEditDrive = function(drive) {

        return (
            drive &&
            drive.can_edit === true
        );
    };


    /* ============================================================
       APPLY PERMISSION
       ============================================================ */

    c.canApplyDrive = function(drive) {

        if (!drive) {
            return false;
        }

        return (
            drive.is_eligible === true &&
            drive.has_applied !== true &&
            drive.can_apply === true
        );
    };


    /* ============================================================
       INITIAL DRIVES
       ============================================================ */

    c.filteredDrives =
        angular.copy(
            c.data.drives || []
        );


    /* ============================================================
       FILTERS
       ============================================================ */

    c.applyFilters = function() {

        var drives =
            c.data.drives || [];

        var search =
            (c.searchText || '')
                .toString()
                .toLowerCase()
                .trim();

        var status =
            (c.statusFilter || '')
                .toString()
                .toLowerCase()
                .trim();

        var branch =
            (c.branchFilter || '')
                .toString()
                .toLowerCase()
                .trim();


        c.filteredDrives =
            drives.filter(function(drive) {

                var searchable = [

                    drive.drive_name,

                    drive.company_name,

                    drive.job_role,

                    drive.skills,

                    drive.mandatory_skills,

                    drive.eligible_branches,

                    drive.company_location

                ]
                .join(' ')
                .toLowerCase();


                if (
                    search &&
                    searchable.indexOf(search) === -1
                ) {

                    return false;
                }


                if (
                    status &&
                    (drive.status || '')
                        .toLowerCase() !== status
                ) {

                    return false;
                }


                if (branch) {

                    var branches =
                        (
                            drive.eligible_branches ||
                            ''
                        )
                        .toLowerCase();


                    if (
                        branches.indexOf(branch) === -1
                    ) {

                        return false;
                    }
                }


                return true;
            });
    };


    /* ============================================================
       WATCH FILTERS
       ============================================================ */

    $scope.$watchGroup(

        [

            function() {
                return c.searchText;
            },

            function() {
                return c.statusFilter;
            },

            function() {
                return c.branchFilter;
            }

        ],

        function() {

            c.applyFilters();
        }
    );


    /* ============================================================
       VIEW DRIVE
       ============================================================ */

    c.viewDrive = function(drive) {

        if (
            !drive ||
            !drive.sys_id
        ) {

            return;
        }


        /*
         * Students can view only eligible drives.
         */

        if (
            c.isStudent &&
            drive.is_eligible !== true
        ) {

            return;
        }


        /*
         * Non-students need can_view permission.
         */

        if (
            !drive.can_view &&
            !c.isStudent
        ) {

            return;
        }


        c.server.get({

            action:
                'get_drive',

            sys_id:
                drive.sys_id

        }).then(function(response) {

            if (
                response.data &&
                response.data.selectedDrive
            ) {

                c.selectedDrive =
                    response.data.selectedDrive;

                c.showDriveModal = true;

            } else {

                spUtil.addErrorMessage(

                    response.data.error ||
                    'Unable to load drive details.'

                );
            }

        }, function() {

            spUtil.addErrorMessage(
                'Server error while loading drive.'
            );

        });
    };


    /* ============================================================
       CLOSE DRIVE MODAL
       ============================================================ */

    c.closeDriveModal = function() {

        c.showDriveModal = false;

        c.selectedDrive = null;
    };


    /* ============================================================
       OPEN ADD DRIVE
       ============================================================ */

    c.openAddDrive = function() {

        if (
            !c.showAddDriveButton()
        ) {

            return;
        }


        c.editingDrive = false;


        c.driveForm = {

            drive_name: '',

            company: '',

            status: 'Open',

            registration_deadline: '',

            minimum_cgpa: '',

            max_backlogs: 0,

            drive_date: '',

            eligible_branches: '',

            mandatory_skills: '',

            minimum_optional_skills: 0,

            job_role: '',

            skills: '',

            package: ''
        };


        c.showDriveForm = true;
    };


    /* ============================================================
       EDIT DRIVE
       ============================================================ */

    c.editDrive = function(drive) {

        if (
            !drive ||
            !drive.can_edit
        ) {

            return;
        }


        c.editingDrive = true;


        c.driveForm = {

            sys_id:
                drive.sys_id,

            drive_name:
                drive.drive_name || '',

            company:
                drive.company || '',

            status:
                drive.status || 'Open',

            registration_deadline:
                drive.registration_deadline || '',

            minimum_cgpa:
                drive.minimum_cgpa || '',

            max_backlogs:
                drive.max_backlogs || 0,

            drive_date:
                drive.drive_date || '',

            eligible_branches:
                drive.eligible_branches || '',

            mandatory_skills:
                drive.mandatory_skills || '',

            minimum_optional_skills:
                drive.minimum_optional_skills || 0,

            job_role:
                drive.job_role || '',

            skills:
                drive.skills || '',

            package:
                drive.package || ''
        };


        c.showDriveForm = true;
    };


    /* ============================================================
       CLOSE DRIVE FORM
       ============================================================ */

    c.closeDriveForm = function() {

        c.showDriveForm = false;

        c.driveForm = null;

        c.editingDrive = false;
    };


    /* ============================================================
       SAVE PLACEMENT DRIVE
       ============================================================ */

    c.saveDrive = function() {

        /* -----------------------------------------------------
           ADMIN / INTERVIEWER CHECK
           ----------------------------------------------------- */

        if (!c.isPlacementAdmin && !c.isInterviewer) {

            spUtil.addErrorMessage(
                'You are not authorized to save placement drives.'
            );

            return;
        }


        /* -----------------------------------------------------
           FORM CHECK
           ----------------------------------------------------- */

        if (!c.driveForm) {

            spUtil.addErrorMessage(
                'Placement drive form was not found.'
            );

            return;
        }


        /* -----------------------------------------------------
           REQUIRED FIELD VALIDATION
           ----------------------------------------------------- */

        if (
            !c.driveForm.drive_name ||
            !c.driveForm.drive_name.toString().trim()
        ) {

            spUtil.addErrorMessage(
                'Drive Name is required.'
            );

            return;
        }


        if (!c.driveForm.company) {

            spUtil.addErrorMessage(
                'Company is required.'
            );

            return;
        }


        if (
            !c.driveForm.job_role ||
            !c.driveForm.job_role.toString().trim()
        ) {

            spUtil.addErrorMessage(
                'Job Role is required.'
            );

            return;
        }


        /* -----------------------------------------------------
           PREVENT DOUBLE SUBMIT
           ----------------------------------------------------- */

        if (c.savingDrive === true) {
            return;
        }

        c.savingDrive = true;


        /* -----------------------------------------------------
           RECORD ID
           ----------------------------------------------------- */

        var driveSysId = '';

        if (
            c.editingDrive === true &&
            c.driveForm.sys_id
        ) {

            driveSysId =
                c.driveForm.sys_id.toString();
        }


        /* -----------------------------------------------------
           SAVE
           ----------------------------------------------------- */

        c.server.get({

            action: 'save_drive',

            sys_id: driveSysId,

            drive_name:
                c.driveForm.drive_name || '',

            company:
                c.driveForm.company || '',

            status:
                c.driveForm.status || 'Open',

            registration_deadline:
                c.driveForm.registration_deadline || '',

            minimum_cgpa:
                c.driveForm.minimum_cgpa === null ||
                c.driveForm.minimum_cgpa === undefined
                    ? ''
                    : c.driveForm.minimum_cgpa,

            max_backlogs:
                c.driveForm.max_backlogs === null ||
                c.driveForm.max_backlogs === undefined
                    ? 0
                    : c.driveForm.max_backlogs,

            drive_date:
                c.driveForm.drive_date || '',

            eligible_branches:
                c.driveForm.eligible_branches || '',

            mandatory_skills:
                c.driveForm.mandatory_skills || '',

            minimum_optional_skills:
                c.driveForm.minimum_optional_skills === null ||
                c.driveForm.minimum_optional_skills === undefined
                    ? 0
                    : c.driveForm.minimum_optional_skills,

            job_role:
                c.driveForm.job_role || '',

            skills:
                c.driveForm.skills || '',

            package:
                c.driveForm.package || ''

        }).then(function(response) {

            c.savingDrive = false;


            /* -------------------------------------------------
               NO RESPONSE
               ------------------------------------------------- */

            if (
                !response ||
                !response.data
            ) {

                spUtil.addErrorMessage(
                    'No response received from server.'
                );

                return;
            }


            /* -------------------------------------------------
               SAVE FAILED
               ------------------------------------------------- */

            if (
                response.data.actionSuccess !== true
            ) {

                spUtil.addErrorMessage(

                    response.data.error ||
                    response.data.message ||
                    'Unable to save the placement drive.'

                );

                return;
            }


            /* -------------------------------------------------
               SAVE SUCCESS
               ------------------------------------------------- */

            spUtil.addInfoMessage(

                response.data.message ||

                (
                    driveSysId
                        ? 'Placement drive updated successfully.'
                        : 'Placement drive created successfully.'
                )

            );


            /* -------------------------------------------------
               CLOSE FORM
               ------------------------------------------------- */

            c.closeDriveForm();


            /* -------------------------------------------------
               REFRESH DATA
               ------------------------------------------------- */

            c.refresh();

        }, function(error) {

            c.savingDrive = false;

            spUtil.addErrorMessage(
                'Server error while saving the placement drive.'
            );

        });

    };


    /* ============================================================
       APPLY DRIVE
       ============================================================ */

    c.applyDrive = function(drive) {

        console.log(
            'NEXORA: Apply clicked:',
            drive
        );


        if (!drive) {

            return;
        }


        if (!drive.sys_id) {

            spUtil.addErrorMessage(
                'Placement drive ID is missing.'
            );

            return;
        }


        if (
            drive.has_applied === true
        ) {

            spUtil.addInfoMessage(
                'You have already applied for this drive.'
            );

            return;
        }


        if (
            drive.is_eligible !== true
        ) {

            spUtil.addErrorMessage(
                'You are not eligible for this placement drive.'
            );

            return;
        }


        if (
            drive.can_apply !== true
        ) {

            spUtil.addErrorMessage(
                'You are not allowed to apply for this placement drive.'
            );

            return;
        }


        c.applyDriveData =
            angular.copy(drive);


        console.log(
            'NEXORA: applyDriveData:',
            c.applyDriveData
        );


        c.showApplyModal = true;
    };


    /* ============================================================
       CLOSE APPLY MODAL
       ============================================================ */

    c.closeApplyModal = function() {

        c.showApplyModal = false;

        c.applyDriveData = null;
    };


    /* ============================================================
       CONFIRM APPLICATION
       ============================================================ */

   /* ============================================================
   CONFIRM APPLICATION
   ============================================================ */

c.confirmApplication = function() {

    console.log('NEXORA: CONFIRM CLICKED');

    if (!c.applyDriveData) {

        spUtil.addErrorMessage(
            'Placement drive information is missing.'
        );

        console.error(
            'NEXORA: applyDriveData is missing'
        );

        return;
    }

    if (!c.applyDriveData.sys_id) {

        spUtil.addErrorMessage(
            'Placement drive ID is missing.'
        );

        console.error(
            'NEXORA: sys_id missing:',
            c.applyDriveData
        );

        return;
    }

    if (c.applying === true) {
        return;
    }

    var driveSysId =
        c.applyDriveData.sys_id.toString();

    console.log(
        'NEXORA: DRIVE SYS ID =',
        driveSysId
    );

    c.applying = true;


    /* ========================================================
       SEND TO SERVER
       ======================================================== */

    c.server.get({

        action: 'apply',

        drive_sys_id: driveSysId

    }).then(

        function(response) {

            console.log(
                'NEXORA: SERVER RESPONSE',
                response
            );


            c.applying = false;


            /* =================================================
               CHECK RESPONSE
               ================================================= */

            if (!response) {

                console.error(
                    'NEXORA: RESPONSE IS NULL'
                );

                spUtil.addErrorMessage(
                    'No response received from ServiceNow.'
                );

                return;
            }


            if (!response.data) {

                console.error(
                    'NEXORA: response.data is missing',
                    response
                );

                spUtil.addErrorMessage(
                    'ServiceNow returned an empty response.'
                );

                return;
            }


            console.log(
                'NEXORA: RESPONSE DATA',
                response.data
            );


            /* =================================================
               SUCCESS
               ================================================= */

            if (
                response.data.actionSuccess === true
            ) {

                console.log(
                    'NEXORA: APPLICATION CREATED',
                    response.data.application_sys_id
                );


                spUtil.addInfoMessage(

                    response.data.message ||
                    'Application submitted successfully.'

                );


                /*
                 * Update current drive
                 */

                if (c.applyDriveData) {

                    c.applyDriveData.has_applied =
                        true;

                    c.applyDriveData.can_apply =
                        false;

                    c.applyDriveData.application_sys_id =
                        response.data.application_sys_id || '';
                }


                /*
                 * Close confirmation modal
                 */

                c.showApplyModal = false;

                c.applyDriveData = null;


                /*
                 * Refresh drives
                 */

                c.refresh();


                return;
            }


            /* =================================================
               SERVER RETURNED ERROR
               ================================================= */

            console.error(
                'NEXORA: APPLY FAILED'
            );

            console.error(
                'ERROR:',
                response.data.error
            );

            console.error(
                'MESSAGE:',
                response.data.message
            );

            console.error(
                'FULL DATA:',
                response.data
            );


            spUtil.addErrorMessage(

                response.data.error ||

                response.data.message ||

                'Application was not created.'

            );

        },

        function(error) {

            c.applying = false;


            console.error(
                'NEXORA: SERVER REQUEST FAILED',
                error
            );


            spUtil.addErrorMessage(
                'ServiceNow server request failed.'
            );

        }
    );
};

    /* ============================================================
       REFRESH
       ============================================================ */

    c.refresh = function() {

        c.server.get({

            action:
                'refresh'

        }).then(

            function(response) {

                /* ----------------------------------------------
                   Update drives
                   ---------------------------------------------- */

                c.data.drives =
                    response.data.drives || [];


                /* ----------------------------------------------
                   Update summary
                   ---------------------------------------------- */

                c.data.summary =
                    response.data.summary ||
                    c.data.summary;


                /* ----------------------------------------------
                   Update companies
                   ---------------------------------------------- */

                c.data.companies =
                    response.data.companies ||
                    c.data.companies;


                /* ----------------------------------------------
                   Update branches
                   ---------------------------------------------- */

                c.data.branches =
                    response.data.branches ||
                    c.data.branches;


                /* ----------------------------------------------
                   Update interviewer debug
                   ---------------------------------------------- */

                c.data.debug_interviewer =
                    response.data.debug_interviewer ||
                    c.data.debug_interviewer ||
                    {};


                c.debugInterviewer =
                    c.data.debug_interviewer ||
                    {};


                /* ----------------------------------------------
                   Update student debug
                   ---------------------------------------------- */

                c.data.debug_student =
                    response.data.debug_student ||
                    c.data.debug_student ||
                    {};


                c.debugStudent =
                    c.data.debug_student ||
                    {};


                /* ----------------------------------------------
                   Rebuild filtered drives
                   ---------------------------------------------- */

                c.filteredDrives =
                    angular.copy(
                        c.data.drives
                    );


                c.applyFilters();

            },

            function() {

                spUtil.addErrorMessage(
                    'Unable to refresh placement drives.'
                );

            }
        );
    };


    /* ============================================================
       RESET FILTERS
       ============================================================ */

    c.resetFilters = function() {

        c.searchText = '';

        c.statusFilter = '';

        c.branchFilter = '';

        c.applyFilters();
    };


    /* ============================================================
       STATUS CLASS
       ============================================================ */

    c.getStatusClass = function(status) {

        status =
            (status || '')
                .toString()
                .toLowerCase();


        if (
            status === 'open'
        ) {

            return 'status-open';
        }


        if (
            status === 'closed'
        ) {

            return 'status-closed';
        }


        return 'status-default';
    };


    /* ============================================================
       PERCENTAGE
       ============================================================ */

    c.getPercentage = function(
        value,
        total
    ) {

        value =
            parseInt(
                value || 0,
                10
            );


        total =
            parseInt(
                total || 0,
                10
            );


        if (
            total <= 0
        ) {

            return 0;
        }


        var percentage =
            (value / total) * 100;


        if (
            percentage > 100
        ) {

            percentage = 100;
        }


        return Math.round(
            percentage
        );
    };


    /* ============================================================
       DEBUG HELPERS
       ============================================================ */

    c.getInterviewerDebug = function() {

        return c.debugInterviewer || {};
    };


    c.getStudentDebug = function() {

        return c.debugStudent || {};
    };


    c.hasInterviewDebugRecords = function() {

        return (
            c.debugInterviewer &&
            c.debugInterviewer.assigned_drive_details &&
            c.debugInterviewer.assigned_drive_details.length > 0
        );
    };


    c.getLoadedDriveCount = function() {

        return (
            (c.data.drives || []).length
        );
    };


    /* ============================================================
       INITIAL FILTER
       ============================================================ */

    c.applyFilters();

};

sp_widget.css:
/* =========================================================
   NEXORA PLACEMENT DRIVES
   PROFESSIONAL SERVICENOW PORTAL UI
   COMPANY PAGE DESIGN LANGUAGE
   ========================================================= */


/* =========================================================
   MAIN CONTAINER
   ========================================================= */

.placement-wrapper {
    width: 85vw;
    min-height: 100vh;
    padding: 70px !important;
    background: #ffffff !important;
    color: #193b56;
    font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI",
        Roboto, "Helvetica Neue", Arial, sans-serif;
    box-sizing: border-box !important;
}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.placement-header {
    position: relative;
    display: flex;
    justify-content: space-between;
    align-items: center;

    background: #193b56;

    color: #ffffff;

    border-radius: 22px;

    padding: 34px 40px;

    margin-bottom: 22px;

    overflow: hidden;

    border: none;

    box-shadow:
        0 12px 30px rgba(25, 59, 86, 0.12);
}


/* =========================================================
   HEADER DECORATIVE CIRCLES
   ========================================================= */

.placement-header:before,
.placement-header:after {
    content: "";

    position: absolute;

    border:
        1px solid rgba(255, 255, 255, 0.08);

    border-radius: 50%;

    pointer-events: none;
}


.placement-header:before {
    width: 250px;
    height: 250px;

    right: -80px;
    top: -110px;
}


.placement-header:after {
    width: 190px;
    height: 190px;

    right: -35px;
    top: -75px;
}


/* =========================================================
   HEADER CONTENT
   ========================================================= */

.header-content {
    position: relative;

    z-index: 5;

    width: 100%;
    max-width: none;

    margin: 0;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 25px;
}


/* =========================================================
   HEADER TITLE
   ========================================================= */

.header-title-section {
    position: relative;

    z-index: 5;

    flex: 1;

    min-width: 0;
}


.header-label {
    display: block;

    color: #ff6b5b;

    font-size: 15px;

    font-weight: 800;

    letter-spacing: 1.4px;

    margin-bottom: 10px;
}


.header-title-section h1 {
    margin: 0;

    font-size: 32px;

    line-height: 1.15;

    font-weight: 800;

    letter-spacing: 0;

    color: #ffffff;
}


.header-title-section p {
    margin: 12px 0 0;

    max-width: 720px;

    color: #a9c4d9;

    font-size: 15px;

    line-height: 1.5;
}


/* =========================================================
   HEADER ACTIONS
   ========================================================= */

.header-actions {
    position: relative;

    z-index: 10;

    display: flex;

    align-items: center;

    justify-content: flex-end;

    gap: 12px;

    margin-left: 20px;

    flex-shrink: 0;
}


/* =========================================================
   ADD DRIVE BUTTON
   ========================================================= */

.btn-add {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 8px;

    min-height: 44px;

    padding: 10px 18px;

    border: none;

    border-radius: 9px;

    background: #ff6b5b;

    color: #ffffff;

    font-size: 14px;

    font-weight: 700;

    line-height: 1;

    cursor: pointer;

    white-space: nowrap;

    box-shadow:
        0 6px 14px rgba(255, 107, 91, 0.20);

    transition:
        background 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease;
}


.btn-add:hover {
    background: #f45d4d;

    color: #ffffff;

    transform: translateY(-1px);

    box-shadow:
        0 8px 18px rgba(255, 107, 91, 0.25);
}


.btn-add:active {
    transform: translateY(0);
}


.btn-add i {
    margin-right: 0;
}


/* =========================================================
   MAIN CONTENT
   ========================================================= */

.placement-content {
    width: 100%;

    max-width: none;

    margin: 0 auto;

    padding: 0;
}


/* =========================================================
   COMMON BUTTON BASE
   ========================================================= */

.btn {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 7px;

    border: none;

    border-radius: 8px;

    font-family: inherit;

    font-weight: 700;

    cursor: pointer;

    transition:
        background 0.2s ease,
        color 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease;

    outline: none;
}


.btn:hover {
    transform: translateY(-1px);
}


.btn:active {
    transform: translateY(0);
}


.btn:disabled {
    opacity: 0.65;

    cursor: not-allowed;

    transform: none;
}


/* =========================================================
   TOOLBAR
   ========================================================= */

.drive-toolbar {
    width: 100%;

    background: #ffffff;

    border:
        1px solid #e2e9ef;

    border-radius: 12px;

    padding: 15px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    margin-bottom: 22px;

    box-shadow:
        0 3px 12px rgba(25, 59, 86, 0.05);

    box-sizing: border-box;
}


/* =========================================================
   SEARCH BOX
   ========================================================= */

.search-box {
    position: relative;

    flex: 1;

    max-width: none;

    width: 100%;
}


.search-box > i {
    position: absolute;

    left: 16px;

    top: 50%;

    transform: translateY(-50%);

    color: #8aa1b2;

    font-size: 14px;

    z-index: 2;
}


.search-box input {
    width: 100%;

    height: auto;

    min-height: 46px;

    padding: 13px 16px 13px 42px;

    border:
        1px solid #e2e9ef;

    border-radius: 10px;

    box-shadow: none;

    font-size: 14px;

    background: #ffffff;

    color: #193b56;

    outline: none;

    box-sizing: border-box;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


.search-box input::placeholder {
    color: #9aaab5;
}


.search-box input:focus {
    border-color: #ff6b5b;

    box-shadow:
        0 0 0 3px rgba(255, 107, 91, 0.10);

    outline: none;
}


/* =========================================================
   FILTER SECTION
   ========================================================= */

.filter-section {
    display: flex;

    align-items: center;

    gap: 10px;

    flex-shrink: 0;
}


.filter-item {
    position: relative;
}


.filter-item > i {
    position: absolute;

    left: 13px;

    top: 50%;

    transform: translateY(-50%);

    color: #8aa1b2;

    font-size: 12px;

    z-index: 2;

    pointer-events: none;
}


.filter-control {
    min-width: 155px;

    height: 46px;

    border:
        1px solid #e2e9ef;

    border-radius: 9px;

    padding:
        0 12px 0 34px;

    box-shadow: none;

    font-size: 13px;

    background: #ffffff;

    color: #193b56;

    outline: none;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


.filter-control:focus {
    border-color: #ff6b5b;

    box-shadow:
        0 0 0 3px rgba(255, 107, 91, 0.10);

    outline: none;
}


/* =========================================================
   RESET BUTTON
   ========================================================= */

.btn-reset {
    width: 46px;

    height: 46px;

    min-width: 46px;

    padding: 0;

    border-radius: 9px;

    background: #edf3f8;

    color: #193b56;
}


.btn-reset:hover {
    background: #e1ebf2;

    color: #193b56;
}


/* =========================================================
   SUMMARY
   ========================================================= */

.summary-row {
    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 18px;

    margin-bottom: 30px;
}


.summary-card {
    background: #ffffff;

    border:
        1px solid #e1e8ee;

    border-radius: 16px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 15px;

    box-shadow:
        0 6px 18px rgba(25, 59, 86, 0.055);

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}


.summary-card:hover {
    transform: translateY(-3px);

    box-shadow:
        0 12px 28px rgba(25, 59, 86, 0.10);
}


.summary-icon {
    width: 48px;

    height: 48px;

    min-width: 48px;

    border-radius: 12px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #fff0ed;

    color: #e65b4f;

    font-size: 19px;
}


.summary-icon.green {
    background: #e8f5ef;

    color: #258a63;
}


.summary-icon.orange {
    background: #fff0df;

    color: #c97932;
}


.summary-icon.purple {
    background: #f0e9f7;

    color: #765a92;
}


.summary-number {
    font-size: 25px;

    font-weight: 800;

    color: #193b56;

    line-height: 1;
}


.summary-label {
    margin-top: 6px;

    font-size: 12px;

    color: #7c8993;

    font-weight: 600;
}


/* =========================================================
   SECTION HEADER
   ========================================================= */

.section-header {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 18px;
}


.section-eyebrow {
    font-size: 12px;

    font-weight: 800;

    letter-spacing: 1.4px;

    color: #ff6b5b;

    margin-bottom: 5px;
}


.section-header h2 {
    margin: 0;

    font-size: 24px;

    font-weight: 800;

    color: #193b56;
}


.section-header p {
    margin: 5px 0 0;

    color: #7c8993;

    font-size: 13px;
}


/* =========================================================
   DRIVE GRID
   ========================================================= */

.drive-grid {
    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 22px;

    width: 100%;
}


/* =========================================================
   DRIVE CARD
   ========================================================= */

.drive-card {
    background: #ffffff;

    border:
        1px solid #e1e8ee;

    border-radius: 16px;

    overflow: hidden;

    box-shadow:
        0 6px 18px rgba(25, 59, 86, 0.055);

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        border-color 0.2s ease;
}


.drive-card:hover {
    transform: translateY(-3px);

    box-shadow:
        0 12px 28px rgba(25, 59, 86, 0.10);

    border-color: #d5e0e7;
}


/* =========================================================
   CARD TOP
   ========================================================= */

.drive-card-top {
    display: flex;

    align-items: center;

    gap: 14px;

    padding: 22px 22px 16px;

    border-bottom:
        1px solid #edf1f4;
}


/* =========================================================
   COMPANY LOGO
   ========================================================= */

.company-logo {
    width: 54px;

    height: 54px;

    min-width: 54px;

    border-radius: 14px;

    background: #193b56;

    color: #ffffff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 19px;

    font-weight: 800;

    box-shadow:
        0 7px 16px rgba(25, 59, 86, 0.16);
}


.company-info {
    min-width: 0;

    flex: 1;
}


.company-info h3 {
    margin: 0;

    font-size: 18px;

    font-weight: 800;

    color: #193b56;

    line-height: 1.3;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


.drive-name {
    display: block;

    margin-top: 5px;

    font-size: 12px;

    color: #7c8993;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


/* =========================================================
   STATUS BADGE
   ========================================================= */

.status-badge {
    display: inline-flex;

    align-items: center;

    gap: 6px;

    white-space: nowrap;

    border-radius: 5px;

    padding: 5px 9px;

    font-size: 11px;

    font-weight: 750;
}


.status-dot {
    width: 6px;

    height: 6px;

    border-radius: 50%;

    background: currentColor;
}


.status-open {
    background: #e3f5ed;

    color: #258a63;
}


.status-upcoming {
    background: #fff0ed;

    color: #e65b4f;
}


.status-closed {
    background: #fde9e7;

    color: #b84f47;
}


.status-completed {
    background: #f0e9f7;

    color: #765a92;
}


/* =========================================================
   JOB ROLE
   ========================================================= */

.job-role {
    margin: 18px 22px 0;

    padding: 14px;

    background: #f6f9fb;

    border:
        1px solid #e5ebef;

    border-radius: 10px;

    display: flex;

    align-items: center;

    gap: 11px;
}


.job-role-icon {
    width: 36px;

    height: 36px;

    min-width: 36px;

    border-radius: 8px;

    background: #fff0ed;

    color: #e65b4f;

    display: flex;

    align-items: center;

    justify-content: center;
}


.job-role-label {
    display: block;

    font-size: 9px;

    font-weight: 800;

    color: #8aa1b2;

    letter-spacing: 1px;

    margin-bottom: 3px;
}


.job-role strong {
    display: block;

    font-size: 13px;

    color: #193b56;

    font-weight: 700;
}


/* =========================================================
   DRIVE INFORMATION
   ========================================================= */

.drive-information {
    display: grid;

    grid-template-columns:
        1fr 1fr;

    padding: 20px 22px;

    gap: 16px 14px;
}


.info-item {
    display: flex;

    align-items: flex-start;

    gap: 9px;

    min-width: 0;
}


.info-icon {
    width: 29px;

    height: 29px;

    min-width: 29px;

    border-radius: 7px;

    background: #edf3f8;

    color: #607d92;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 11px;
}


.info-label {
    display: block;

    font-size: 10px;

    color: #8aa1b2;

    margin-bottom: 3px;

    font-weight: 600;
}


.info-item strong {
    display: block;

    font-size: 12px;

    color: #193b56;

    font-weight: 700;

    word-break: break-word;
}


/* =========================================================
   PACKAGE
   ========================================================= */

.package-section {
    margin: 0 22px;

    padding: 13px 15px;

    background: #fff3f0;

    border:
        1px solid #ffd9d4;

    border-radius: 10px;

    display: flex;

    align-items: center;

    justify-content: space-between;
}


.package-label {
    display: block;

    font-size: 9px;

    color: #7c8993;

    font-weight: 800;

    letter-spacing: 1px;

    margin-bottom: 2px;
}


.package-section strong {
    color: #d9574b;

    font-size: 14px;

    font-weight: 800;
}


.package-section > i {
    color: #ff6b5b;

    font-size: 18px;
}


/* =========================================================
   SKILLS
   ========================================================= */

.skills-section {
    padding: 20px 22px;
}


.skill-title {
    font-size: 11px;

    font-weight: 800;

    color: #506274;

    margin-bottom: 9px;
}


.skill-title i {
    color: #ff6b5b;

    margin-right: 5px;
}


.skill-list {
    display: flex;

    flex-wrap: wrap;

    gap: 6px;
}


.skill-tag {
    background: #edf3f8;

    color: #506274;

    border:
        1px solid #dce6ed;

    padding: 5px 9px;

    border-radius: 6px;

    font-size: 10px;

    font-weight: 600;
}


/* =========================================================
   ELIGIBILITY
   ========================================================= */

.eligibility-message {
    padding: 0 22px 17px;
}


.eligible,
.not-eligible {
    display: flex;

    align-items: center;

    gap: 10px;

    padding: 11px 12px;

    border-radius: 9px;
}


.eligible {
    background: #eef9f4;

    color: #258a63;

    border:
        1px solid #d7eee4;
}


.not-eligible {
    background: #fff3f1;

    color: #b84f47;

    border:
        1px solid #f4d7d3;
}


.eligible > i,
.not-eligible > i {
    font-size: 17px;
}


.eligible strong,
.not-eligible strong {
    display: block;

    font-size: 11px;

    font-weight: 750;
}


.eligible span,
.not-eligible span {
    display: block;

    font-size: 10px;

    opacity: 0.8;

    margin-top: 2px;
}


/* =========================================================
   MINI STATISTICS
   ========================================================= */

.mini-statistics {
    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    border-top:
        1px solid #edf1f4;

    border-bottom:
        1px solid #edf1f4;
}


.mini-stat {
    text-align: center;

    padding: 14px 5px;
}


.mini-stat + .mini-stat {
    border-left:
        1px solid #edf1f4;
}


.mini-stat strong {
    display: block;

    color: #193b56;

    font-size: 16px;

    font-weight: 800;
}


.mini-stat span {
    display: block;

    margin-top: 3px;

    color: #8aa1b2;

    font-size: 9px;

    font-weight: 600;
}


/* =========================================================
   CARD ACTIONS
   ========================================================= */

.drive-actions {
    display: flex;

    gap: 10px;

    padding: 15px 22px 20px;
}


.drive-actions .btn {
    flex: 1;

    min-height: 42px;

    padding: 10px 14px;

    font-size: 13px;
}


/* =========================================================
   VIEW BUTTON
   ========================================================= */

.btn-view {
    background: #fff0ed;

    color: #d9574b;
}


.btn-view:hover {
    background: #ffe1dc;

    color: #c84f44;
}


/* =========================================================
   EDIT BUTTON
   ========================================================= */

.btn-edit {
    background: #edf3f8;

    color: #193b56;

    border: none;
}


.btn-edit:hover {
    background: #e1ebf2;

    color: #193b56;
}


/* =========================================================
   APPLY BUTTON
   ========================================================= */

.btn-apply {
    background: #ff6b5b;

    color: #ffffff;

    box-shadow:
        0 6px 14px rgba(255, 107, 91, 0.20);
}


.btn-apply:hover {
    background: #f45d4d;

    color: #ffffff;

    box-shadow:
        0 8px 18px rgba(255, 107, 91, 0.25);
}


/* =========================================================
   APPLIED BUTTON
   ========================================================= */

.btn-applied {
    background: #e3f5ed;

    color: #258a63;

    cursor: default;

    box-shadow: none;
}


.btn-applied:hover {
    transform: none;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.empty-state {
    background: #ffffff;

    border:
        1px solid #e2e9ef;

    border-radius: 16px;

    padding: 55px 25px;

    text-align: center;

    box-shadow:
        0 6px 18px rgba(25, 59, 86, 0.04);
}


.empty-icon {
    width: 65px;

    height: 65px;

    margin: 0 auto 15px;

    border-radius: 50%;

    background: #edf3f8;

    color: #8aa1b2;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;
}


.empty-state h3 {
    margin: 0;

    color: #193b56;

    font-size: 20px;

    font-weight: 800;
}


.empty-state p {
    margin: 8px 0 0;

    color: #7c8993;

    font-size: 14px;
}


/* =========================================================
   MODAL BACKDROP
   ========================================================= */

.modal-backdrop-custom {
    position: fixed;

    inset: 0;

    background: rgba(25, 59, 86, 0.68);

    backdrop-filter: blur(5px);

    z-index: 9999;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 25px;
}


/* =========================================================
   DRIVE MODALS
   ========================================================= */

.drive-modal,
.drive-form-modal {
    width: 100%;

    max-width: 1050px;

    max-height: 92vh;

    background: #ffffff;

    border-radius: 18px;

    overflow: hidden;

    box-shadow:
        0 30px 80px rgba(25, 59, 86, 0.25);

    border:
        1px solid rgba(25, 59, 86, 0.08);

    display: flex;

    flex-direction: column;
}


.drive-form-modal {
    max-width: 900px;
}


/* =========================================================
   MODAL HEADER
   ========================================================= */

.modal-header-custom {
    position: relative;

    background: #193b56;

    color: #ffffff;

    padding: 25px 28px;

    display: flex;

    justify-content: space-between;

    align-items: flex-start;

    flex-shrink: 0;

    overflow: hidden;
}


.modal-header-custom:after {
    content: "";

    position: absolute;

    width: 210px;

    height: 210px;

    right: -70px;

    top: -120px;

    border:
        1px solid rgba(255, 255, 255, 0.08);

    border-radius: 50%;

    pointer-events: none;
}


.modal-company {
    position: relative;

    z-index: 2;

    color: #ff6b5b;

    font-size: 10px;

    font-weight: 800;

    letter-spacing: 1.5px;

    margin-bottom: 5px;
}


.modal-header-custom h2 {
    position: relative;

    z-index: 2;

    margin: 0;

    font-size: 23px;

    font-weight: 800;

    color: #ffffff;
}


.modal-header-custom p {
    position: relative;

    z-index: 2;

    margin: 7px 0 0;

    color: #a9c4d9;

    font-size: 13px;
}


.modal-header-custom p i {
    margin-right: 5px;
}


/* =========================================================
   CLOSE BUTTON
   ========================================================= */

.close-button {
    position: relative;

    z-index: 10;

    width: 38px;

    height: 38px;

    border: 0;

    border-radius: 9px;

    background: rgba(255, 255, 255, 0.10);

    color: #ffffff;

    cursor: pointer;

    font-size: 16px;

    transition:
        background 0.2s ease,
        transform 0.2s ease;
}


.close-button:hover {
    background: rgba(255, 107, 91, 0.22);

    transform: translateY(-1px);
}


/* =========================================================
   MODAL BODY
   ========================================================= */

.modal-body-custom {
    overflow-y: auto;

    padding: 25px 28px;

    background: #f5f8fa;
}


.modal-body-custom::-webkit-scrollbar {
    width: 7px;
}


.modal-body-custom::-webkit-scrollbar-track {
    background: #edf3f8;
}


.modal-body-custom::-webkit-scrollbar-thumb {
    background: #b9c7d0;

    border-radius: 10px;
}


/* =========================================================
   DETAIL / FORM SECTIONS
   ========================================================= */

.detail-section,
.form-section {
    background: #ffffff;

    border:
        1px solid #e2e9ef;

    border-radius: 13px;

    padding: 20px;

    margin-bottom: 18px;

    box-shadow:
        0 3px 10px rgba(25, 59, 86, 0.025);
}


.detail-section:last-child,
.form-section:last-child {
    margin-bottom: 0;
}


/* =========================================================
   SECTION HEADERS
   ========================================================= */

.detail-section-header,
.form-section-title {
    display: flex;

    align-items: center;

    gap: 12px;

    margin-bottom: 18px;
}


.detail-section-icon,
.form-section-icon {
    width: 38px;

    height: 38px;

    min-width: 38px;

    border-radius: 9px;

    background: #fff0ed;

    color: #e65b4f;

    display: flex;

    align-items: center;

    justify-content: center;
}


.detail-section-header h3,
.form-section-title h3 {
    margin: 0;

    font-size: 16px;

    color: #193b56;

    font-weight: 800;
}


.detail-section-header p,
.form-section-title p {
    margin: 3px 0 0;

    color: #7c8993;

    font-size: 11px;
}


/* =========================================================
   DETAIL GRID
   ========================================================= */

.detail-grid,
.company-detail-grid {
    display: grid;

    grid-template-columns:
        repeat(2, 1fr);

    gap: 1px;

    background: #dfe7eb;

    border:
        1px solid #dfe7eb;

    border-radius: 10px;

    overflow: hidden;
}


.detail-item {
    background: #ffffff;

    padding: 14px;

    min-height: 70px;
}


.detail-item label {
    display: block;

    color: #8aa1b2;

    font-size: 10px;

    font-weight: 650;

    margin-bottom: 6px;
}


.detail-item span,
.detail-item a {
    color: #193b56;

    font-size: 13px;

    font-weight: 700;
}


.detail-item a {
    color: #e65b4f;

    text-decoration: none;
}


.detail-item a:hover {
    color: #c84f44;

    text-decoration: underline;
}


/* =========================================================
   SKILL DETAIL
   ========================================================= */

.skills-detail {
    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 12px;
}


.skill-detail-card {
    padding: 15px;

    background: #f6f9fb;

    border:
        1px solid #e5ebef;

    border-radius: 10px;
}


.skill-detail-card label {
    display: block;

    color: #5d6d7e;

    font-size: 10px;

    font-weight: 700;

    margin-bottom: 7px;
}


.skill-detail-card p {
    margin: 0;

    color: #314558;

    font-size: 12px;

    line-height: 1.6;
}


/* =========================================================
   APPLICATION STATISTICS
   ========================================================= */

.application-stat-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 10px;
}


.application-stat {
    text-align: center;

    padding: 17px 10px;

    border:
        1px solid #dfe7eb;

    border-radius: 10px;

    background: #ffffff;
}


.application-stat.selected {
    background: #eef9f4;

    border-color: #cfe9dc;
}


.application-stat.rejected {
    background: #fff3f1;

    border-color: #f1cfca;
}


.stat-number {
    font-size: 21px;

    font-weight: 800;

    color: #193b56;
}


.stat-title {
    margin-top: 4px;

    font-size: 9px;

    color: #8aa1b2;

    font-weight: 650;
}


/* =========================================================
   PROGRESS
   ========================================================= */

.progress-item {
    margin-bottom: 17px;
}


.progress-item:last-child {
    margin-bottom: 0;
}


.progress-header {
    display: flex;

    justify-content: space-between;

    margin-bottom: 7px;
}


.progress-header span {
    font-size: 11px;

    color: #506274;

    font-weight: 600;
}


.progress-header strong {
    font-size: 11px;

    color: #193b56;
}


.progress-bar-container {
    height: 8px;

    background: #dce5ea;

    border-radius: 20px;

    overflow: hidden;
}


.progress-bar-fill {
    height: 100%;

    background: linear-gradient(
        90deg,
        #ff6b5b,
        #ff9b90
    );

    border-radius: 20px;

    transition: width 0.4s ease;
}


.selected-fill {
    background: linear-gradient(
        90deg,
        #258a63,
        #66b996
    );
}


/* =========================================================
   APPLICATION TABLE
   ========================================================= */

.section-title-row {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 15px;
}


.section-title-row .detail-section-header {
    margin-bottom: 0;
}


.record-count {
    background: #fff0ed;

    color: #d9574b;

    padding: 7px 11px;

    border-radius: 20px;

    font-size: 10px;

    font-weight: 700;
}


.application-table-wrapper {
    overflow-x: auto;

    border:
        1px solid #dfe7eb;

    border-radius: 10px;
}


.application-table {
    width: 100%;

    border-collapse: collapse;

    min-width: 750px;
}


.application-table th {
    background: #f3f7f8;

    color: #5d6d7e;

    text-align: left;

    font-size: 10px;

    font-weight: 750;

    text-transform: uppercase;

    letter-spacing: 0.5px;

    padding: 12px;

    border-bottom:
        1px solid #dfe7eb;
}


.application-table td {
    padding: 13px 12px;

    color: #506274;

    font-size: 11px;

    border-bottom:
        1px solid #edf1f3;
}


.application-table tbody tr {
    transition:
        background 0.15s ease;
}


.application-table tbody tr:hover {
    background: #fff8f7;
}


.application-table tbody tr:last-child td {
    border-bottom: 0;
}


/* =========================================================
   APPLICATION STATUS
   ========================================================= */

.application-status {
    display: inline-block;

    padding: 5px 8px;

    border-radius: 5px;

    font-size: 9px;

    font-weight: 750;

    text-transform: capitalize;
}


.status-applied {
    background: #fff0ed;

    color: #d9574b;
}


.status-interview {
    background: #fff3dc;

    color: #a8662b;
}


.status-selected {
    background: #e3f5ed;

    color: #258a63;
}


.status-rejected {
    background: #fde9e7;

    color: #b84f47;
}


/* =========================================================
   NO APPLICATIONS
   ========================================================= */

.no-applications {
    padding: 35px 20px;

    text-align: center;

    background: #f6f9fb;

    border-radius: 10px;

    border:
        1px solid #e5ebef;
}


.no-applications i {
    font-size: 25px;

    color: #c7d1d8;
}


.no-applications p {
    margin: 8px 0 0;

    color: #718096;

    font-size: 12px;
}


/* =========================================================
   MODAL FOOTER
   ========================================================= */

.modal-footer-custom {
    padding: 15px 25px;

    background: #ffffff;

    border-top:
        1px solid #e2e9ef;

    display: flex;

    justify-content: flex-end;

    gap: 10px;

    flex-shrink: 0;
}


/* =========================================================
   SECONDARY BUTTON
   ========================================================= */

.btn-secondary {
    background: #edf3f8;

    color: #193b56;

    padding: 11px 18px;
}


.btn-secondary:hover {
    background: #e1ebf2;

    color: #193b56;
}


/* =========================================================
   LARGE APPLY BUTTON
   ========================================================= */

.btn-apply-large {
    background: #ff6b5b;

    color: #ffffff;

    padding: 11px 20px;

    box-shadow:
        0 6px 14px rgba(255, 107, 91, 0.20);
}


.btn-apply-large:hover {
    background: #f45d4d;

    color: #ffffff;

    box-shadow:
        0 8px 18px rgba(255, 107, 91, 0.25);
}


/* =========================================================
   CONFIRMATION MODAL
   ========================================================= */

.confirmation-modal {
    width: 100%;

    max-width: 470px;

    background: #ffffff;

    border-radius: 18px;

    padding: 35px;

    text-align: center;

    border:
        1px solid rgba(25, 59, 86, 0.08);

    box-shadow:
        0 30px 80px rgba(25, 59, 86, 0.25);

    box-sizing: border-box;
}


.confirmation-icon {
    width: 65px;

    height: 65px;

    margin: 0 auto 18px;

    border-radius: 50%;

    background: #fff0ed;

    color: #ff6b5b;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;
}


.confirmation-modal h2 {
    margin: 0;

    color: #193b56;

    font-size: 21px;

    font-weight: 800;
}


.confirmation-modal > p {
    margin: 12px 0 22px;

    color: #5d6d7e;

    font-size: 13px;

    line-height: 1.6;
}


.confirmation-info {
    display: grid;

    grid-template-columns:
        1fr 1fr;

    gap: 10px;

    margin-bottom: 23px;
}


.confirmation-info > div {
    padding: 13px;

    background: #f6f9fb;

    border:
        1px solid #e5ebef;

    border-radius: 9px;
}


.confirmation-info span {
    display: block;

    color: #8aa1b2;

    font-size: 9px;

    margin-bottom: 4px;
}


.confirmation-info strong {
    display: block;

    color: #193b56;

    font-size: 11px;

    font-weight: 700;
}


.confirmation-actions {
    display: flex;

    gap: 10px;
}


.confirmation-actions .btn {
    flex: 1;

    padding: 12px;
}


/* =========================================================
   CONFIRM BUTTON
   ========================================================= */

.btn-confirm {
    background: #ff6b5b;

    color: #ffffff;

    box-shadow:
        0 6px 14px rgba(255, 107, 91, 0.20);
}


.btn-confirm:hover {
    background: #f45d4d;

    color: #ffffff;

    box-shadow:
        0 8px 18px rgba(255, 107, 91, 0.25);
}


.btn-confirm:disabled {
    background: #f2a49b;

    color: #ffffff;

    box-shadow: none;

    cursor: not-allowed;
}


/* =========================================================
   FORM
   ========================================================= */

.form-grid {
    display: grid;

    grid-template-columns:
        repeat(2, 1fr);

    gap: 17px;
}


.form-group {
    margin: 0;
}


.form-group.full-width {
    grid-column: 1 / -1;
}


.form-group label {
    display: block;

    margin-bottom: 7px;

    color: #193b56;

    font-size: 11px;

    font-weight: 700;
}


.form-group label span {
    color: #e65b4f;

    margin-left: 2px;
}


.form-group .form-control {
    width: 100%;

    height: 43px;

    border:
        1px solid #d4dee4;

    border-radius: 8px;

    box-shadow: none;

    color: #193b56;

    font-size: 12px;

    background: #ffffff;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;

    box-sizing: border-box;
}


.form-group textarea.form-control {
    height: auto;

    resize: vertical;

    min-height: 90px;

    padding: 11px;
}


.form-group .form-control:focus {
    border-color: #ff6b5b;

    box-shadow:
        0 0 0 3px rgba(255, 107, 91, 0.10);

    outline: none;
}


/* =========================================================
   SAVE BUTTON
   ========================================================= */

.btn-save {
    background: #ff6b5b;

    color: #ffffff;

    padding: 11px 20px;

    box-shadow:
        0 6px 14px rgba(255, 107, 91, 0.20);
}


.btn-save:hover {
    background: #f45d4d;

    color: #ffffff;

    box-shadow:
        0 8px 18px rgba(255, 107, 91, 0.25);
}


/* =========================================================
   RESPONSIVE - 1200px
   ========================================================= */

@media (max-width: 1200px) {

    .placement-wrapper {
        padding: 45px !important;
    }

    .summary-row {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

    .drive-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

}


/* =========================================================
   RESPONSIVE - 900px
   ========================================================= */

@media (max-width: 900px) {

    .placement-wrapper {
        padding: 28px !important;
    }


    .placement-header {
        padding: 28px;
    }


    .header-content {
        align-items: flex-start;

        flex-direction: column;

        gap: 20px;
    }


    .header-actions {
        width: 100%;

        margin-left: 0;

        justify-content: flex-start;
    }


    .placement-content {
        padding: 0;
    }


    .drive-toolbar {
        flex-direction: column;

        align-items: stretch;
    }


    .search-box {
        max-width: none;
    }


    .filter-section {
        width: 100%;
    }


    .filter-item {
        flex: 1;
    }


    .filter-control {
        width: 100%;
    }


    .drive-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

}


/* =========================================================
   RESPONSIVE - 767px
   ========================================================= */

@media (max-width: 767px) {

    .placement-wrapper {
        width: 100%;

        padding: 12px 12px 30px !important;
    }


    .placement-header {
        flex-direction: column;

        align-items: stretch;

        gap: 20px;

        padding: 25px 22px;

        border-radius: 18px;
    }


    .header-title-section h1 {
        font-size: 27px;
    }


    .header-title-section p {
        font-size: 14px;
    }


    .header-actions {
        width: 100%;

        margin-left: 0;

        justify-content: space-between;
    }


    .btn-add {
        flex: 1;

        width: 100%;
    }


    .summary-row {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));

        gap: 12px;
    }


    .summary-card {
        padding: 16px;
    }


    .summary-icon {
        width: 42px;

        height: 42px;

        min-width: 42px;
    }


    .summary-number {
        font-size: 22px;
    }


    .drive-grid {
        grid-template-columns: 1fr;
    }


    .drive-card-top {
        padding: 18px;
    }


    .drive-information {
        grid-template-columns:
            1fr 1fr;
    }


    .skills-detail {
        grid-template-columns: 1fr;
    }


    .application-stat-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }


    .detail-grid,
    .company-detail-grid {
        grid-template-columns: 1fr;
    }


    .form-grid {
        grid-template-columns: 1fr;
    }


    .form-group.full-width {
        grid-column: auto;
    }


    .modal-backdrop-custom {
        padding: 10px;
    }


    .drive-modal,
    .drive-form-modal {
        max-height: 96vh;

        border-radius: 15px;
    }


    .modal-header-custom {
        padding: 20px;
    }


    .modal-body-custom {
        padding: 15px;
    }


    .modal-footer-custom {
        padding: 12px 15px;
    }

}


/* =========================================================
   RESPONSIVE - 500px
   ========================================================= */

@media (max-width: 500px) {

    .placement-wrapper {
        padding: 10px 10px 25px !important;
    }


    .placement-header {
        padding: 22px 18px;
    }


    .header-title-section h1 {
        font-size: 23px;
    }


    .header-title-section p {
        font-size: 13px;
    }


    .summary-row {
        grid-template-columns: 1fr;
    }


    .filter-section {
        flex-wrap: wrap;
    }


    .filter-item {
        width: calc(50% - 5px);

        flex: none;
    }


    .btn-reset {
        width: 100%;
    }


    .drive-card-top {
        padding: 16px;
    }


    .drive-information {
        grid-template-columns: 1fr;
    }


    .drive-actions {
        flex-wrap: wrap;
    }


    .drive-actions .btn {
        min-width: 45%;
    }


    .confirmation-modal {
        padding: 25px 18px;
    }


    .confirmation-info {
        grid-template-columns: 1fr;
    }


    .confirmation-actions {
        flex-direction: column;
    }


    .company-info h3 {
        font-size: 16px;
    }


    .status-badge {
        font-size: 10px;

        padding: 5px 7px;
    }

}


/* =========================================================
   VERY SMALL DEVICES
   ========================================================= */

@media (max-width: 380px) {

    .summary-card {
        padding: 13px;
    }


    .summary-icon {
        width: 38px;

        height: 38px;

        min-width: 38px;

        font-size: 15px;
    }


    .summary-number {
        font-size: 20px;
    }


    .summary-label {
        font-size: 11px;
    }


    .drive-actions {
        flex-direction: column;
    }


    .drive-actions .btn {
        width: 100%;

        min-width: 100%;
    }

}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

.btn:focus-visible,
.close-button:focus-visible,
.form-control:focus-visible,
.filter-control:focus-visible,
.search-box input:focus-visible {
    outline:
        3px solid rgba(255, 107, 91, 0.25);

    outline-offset: 2px;
}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

    .btn,
    .summary-card,
    .drive-card,
    .progress-bar-fill,
    .close-button {
        transition: none !important;
    }


    .btn:hover,
    .summary-card:hover,
    .drive-card:hover,
    .close-button:hover {
        transform: none !important;
    }

}

sp_widget.script:
(function() {  

    /* ============================================================  
       TABLES  
       ============================================================ */  

    var TABLE_DRIVE       = 'x_snc_college_pl_0_placement_drive';  
    var TABLE_COMPANY     = 'x_snc_college_pl_0_company';  
    var TABLE_STUDENT     = 'x_snc_college_pl_0_student';  
    var TABLE_APPLICATION = 'x_snc_college_pl_0_application';  
    var TABLE_INTERVIEW   = 'x_snc_college_pl_0_interview';  


    /* ============================================================  
       CURRENT USER  
       ============================================================ */  

    var CURRENT_USER = gs.getUserID();  
    var CURRENT_USER_NAME = gs.getUserName();  
    var CURRENT_USER_DISPLAY = gs.getUserDisplayName();  


    /* ============================================================  
       ROLE DETECTION  
       ============================================================ */  

    function userHasRole(roleKeyword) {  

        var roleGR = new GlideRecord('sys_user_has_role');  

        roleGR.addQuery('user', CURRENT_USER);  
        roleGR.addQuery('role.name', 'CONTAINS', roleKeyword);  
        roleGR.setLimit(1);  
        roleGR.query();  

        return roleGR.hasNext();  
    }  


    var hasAdminRole =  
        userHasRole('placement_admin');  

    var hasOfficerRole =  
        userHasRole('placement_officer');  

    var hasInterviewerRole =  
        userHasRole('interviewer');  

    var hasStudentRole =  
        userHasRole('student');  


    data.is_placement_admin = false;  
    data.is_placement_officer = false;  
    data.is_interviewer = false;  
    data.is_student = false;  


    /*  
     * Priority:  
     * Admin > Officer > Interviewer > Student  
     */  

    if (hasAdminRole) {  

        data.is_placement_admin = true;  

    } else if (hasOfficerRole) {  

        data.is_placement_officer = true;  

    } else if (hasInterviewerRole) {  

        data.is_interviewer = true;  

    } else if (hasStudentRole) {  

        data.is_student = true;  
    }  


    /* ============================================================  
       GENERAL APPLY PERMISSION  
       ============================================================ */  

    data.can_apply =  
        data.is_student ||  
        data.is_placement_officer;  


    /* ============================================================  
       BASIC HELPERS  
       ============================================================ */  

    function value(gr, field) {  

        if (!gr || !gr.isValidField(field)) {  
            return '';  
        }  

        var v = gr.getValue(field);  

        return v === null || v === undefined  
            ? ''  
            : v.toString();  
    }  


    function displayValue(gr, field) {  

        if (!gr || !gr.isValidField(field)) {  
            return '';  
        }  

        var display = gr.getDisplayValue(field);  

        if (  
            display !== null &&  
            display !== undefined &&  
            display !== ''  
        ) {  
            return display.toString();  
        }  

        var raw = gr.getValue(field);  

        if (  
            raw !== null &&  
            raw !== undefined &&  
            raw !== ''  
        ) {  
            return raw.toString();  
        }  

        return '';  
    }  


    function safeValue(gr, field) {  

        if (!gr || !gr.isValidField(field)) {  
            return '';  
        }  

        var display = gr.getDisplayValue(field);  

        if (  
            display !== null &&  
            display !== undefined &&  
            display !== ''  
        ) {  
            return display.toString();  
        }  

        var raw = gr.getValue(field);  

        if (  
            raw !== null &&  
            raw !== undefined &&  
            raw !== ''  
        ) {  
            return raw.toString();  
        }  

        return '';  
    }  


    /* ============================================================  
       NEW HELPER  
       FIND CORRECT CHOICE VALUE FROM LABEL OR VALUE  
       ============================================================ */  

    function getChoiceValue(  
        tableName,  
        fieldName,  
        desiredText  
    ) {  

        if (!desiredText) {  
            return '';  
        }  

        var wanted =  
            normalizeText(desiredText);  

        var choice =  
            new GlideRecord('sys_choice');  

        choice.addQuery(  
            'name',  
            tableName  
        );  

        choice.addQuery(  
            'element',  
            fieldName  
        );  

        choice.addQuery(  
            'inactive',  
            false  
        );  

        choice.query();  

        while (choice.next()) {  

            var choiceValue =  
                choice.getValue('value') || '';  

            var choiceLabel =  
                choice.getValue('label') || '';  

            if (  
                normalizeText(choiceValue) === wanted ||  
                normalizeText(choiceLabel) === wanted  
            ) {  

                return choiceValue.toString();  
            }  
        }  

        return '';  
    }  


    /* ============================================================  
       SET CHOICE SAFELY  
       ============================================================ */  

    function setChoiceIfAvailable(  
        gr,  
        tableName,  
        fieldName,  
        desiredText  
    ) {  

        if (  
            !gr ||  
            !gr.isValidField(fieldName)  
        ) {  

            return false;  
        }  

        var choiceValue =  
            getChoiceValue(  
                tableName,  
                fieldName,  
                desiredText  
            );  

        if (choiceValue) {  

            gr.setValue(  
                fieldName,  
                choiceValue  
            );  

            return true;  
        }  

        /*  
         * If there is no sys_choice record, try the supplied  
         * value directly. This supports non-choice fields and  
         * unusual configurations.  
         */  

        try {  

            gr.setValue(  
                fieldName,  
                desiredText  
            );  

            return true;  

        } catch (choiceException) {  

            return false;  
        }  
    }  


    function normalizeText(text) {  

        return (text || '')  
            .toString()  
            .trim()  
            .toLowerCase();  
    }  


    function normalizeEligibilityText(text) {  

        return (text || '')  
            .toString()  
            .toLowerCase()  
            .replace(/[^a-z0-9]/g, '')  
            .trim();  
    }  


    function containsIgnoreCase(text, search) {  

        if (!text || !search) {  
            return false;  
        }  

        return normalizeText(text)  
            .indexOf(normalizeText(search)) !== -1;  
    }  


    function splitValues(text) {  

        var result = [];  

        if (!text) {  
            return result;  
        }  

        var arr = text.toString().split(',');  

        for (var i = 0; i < arr.length; i++) {  

            var item = arr[i]  
                .toString()  
                .trim()  
                .toLowerCase();  

            if (item) {  
                result.push(item);  
            }  
        }  

        return result;  
    }  


    /* ============================================================  
       STATUS HELPERS  
       ============================================================ */  

    function getDriveStatusInfo(drive) {  

        var rawStatus =  
            value(drive, 'status');  

        var displayStatus =  
            displayValue(drive, 'status');  

        var normalizedRaw =  
            normalizeText(rawStatus);  

        var normalizedDisplay =  
            normalizeText(displayStatus);  

        var isOpen =  
            normalizedRaw === 'open' ||  
            normalizedDisplay === 'open';  

        if (  
            !normalizedRaw &&  
            !normalizedDisplay  
        ) {  
            isOpen = true;  
        }  

        return {  

            raw: rawStatus,  

            display: displayStatus,  

            normalized_raw:  
                normalizedRaw,  

            normalized_display:  
                normalizedDisplay,  

            is_open:  
                isOpen  
        };  
    }  


    /* ============================================================  
       ACRONYM  
       ============================================================ */  

    function getAcronym(text) {  

        if (!text) {  
            return '';  
        }  

        var cleaned =  
            text  
                .toString()  
                .replace(/[^a-zA-Z0-9]+/g, ' ')  
                .trim();  

        if (!cleaned) {  
            return '';  
        }  

        var words =  
            cleaned.split(/\s+/);  

        var acronym = '';  

        for (var i = 0; i < words.length; i++) {  

            if (words[i]) {  
                acronym += words[i].charAt(0);  
            }  
        }  

        return acronym.toLowerCase();  
    }  


    /* ============================================================  
       GENERAL ELIGIBILITY VALUE MATCH  
       ============================================================ */  

    function eligibilityValueMatches(  
        studentValue,  
        requiredValue  
    ) {  

        var student =  
            normalizeEligibilityText(studentValue);  

        var required =  
            normalizeEligibilityText(requiredValue);  

        if (!student || !required) {  
            return false;  
        }  

        if (student === required) {  
            return true;  
        }  

        var studentAcronym =  
            getAcronym(studentValue);  

        var requiredAcronym =  
            getAcronym(requiredValue);  

        if (  
            studentAcronym &&  
            requiredAcronym  
        ) {  

            if (  
                studentAcronym === required ||  
                requiredAcronym === student  
            ) {  
                return true;  
            }  
        }  

        if (  
            student.length >= 3 &&  
            required.length >= 3  
        ) {  

            if (  
                student.indexOf(required) >= 0 ||  
                required.indexOf(student) >= 0  
            ) {  
                return true;  
            }  
        }  

        return false;  
    }  


    /* ============================================================  
       BRANCH MATCHING  
       ============================================================ */  

    function branchMatches(  
        studentBranch,  
        eligibleBranch  
    ) {  

        if (  
            !studentBranch ||  
            !eligibleBranch  
        ) {  
            return false;  
        }  

        var student =  
            normalizeEligibilityText(studentBranch);  

        var eligible =  
            normalizeEligibilityText(eligibleBranch);  

        if (  
            !student ||  
            !eligible  
        ) {  
            return false;  
        }  

        if (student === eligible) {  
            return true;  
        }  

        var studentAcronym =  
            getAcronym(studentBranch);  

        var eligibleAcronym =  
            getAcronym(eligibleBranch);  

        if (  
            studentAcronym === eligible ||  
            eligibleAcronym === student  
        ) {  
            return true;  
        }  


        var branchAliases = {  

            cse: [  
                'computer science engineering',  
                'computer science and engineering',  
                'computer science'  
            ],  

            ece: [  
                'electronics communication engineering',  
                'electronics and communication engineering',  
                'electronics communication',  
                'electronics'  
            ],  

            eee: [  
                'electrical electronics engineering',  
                'electrical and electronics engineering',  
                'electrical engineering'  
            ],  

            it: [  
                'information technology'  
            ],  

            mech: [  
                'mechanical engineering',  
                'mechanical'  
            ],  

            civil: [  
                'civil engineering'  
            ],  

            aiml: [  
                'artificial intelligence machine learning',  
                'artificial intelligence and machine learning',  
                'ai ml',  
                'ai and ml'  
            ],  

            aids: [  
                'artificial intelligence data science',  
                'artificial intelligence and data science',  
                'ai data science'  
            ],  

            ds: [  
                'data science'  
            ]  
        };  


        function aliasMatches(  
            shortName,  
            fullName  
        ) {  

            var aliases =  
                branchAliases[shortName];  

            if (!aliases) {  
                return false;  
            }  

            for (  
                var i = 0;  
                i < aliases.length;  
                i++  
            ) {  

                if (  
                    normalizeEligibilityText(  
                        aliases[i]  
                    ) ===  
                    normalizeEligibilityText(  
                        fullName  
                    )  
                ) {  
                    return true;  
                }  
            }  

            return false;  
        }  


        if (  
            aliasMatches(  
                student,  
                eligibleBranch  
            ) ||  
            aliasMatches(  
                eligible,  
                studentBranch  
            )  
        ) {  
            return true;  
        }  


        if (  
            student.length >= 3 &&  
            eligible.length >= 3  
        ) {  

            if (  
                student.indexOf(eligible) >= 0 ||  
                eligible.indexOf(student) >= 0  
            ) {  
                return true;  
            }  
        }  

        return false;  
    }  


    /* ============================================================  
       CURRENT STUDENT  
       ============================================================ */  

    function getCurrentStudent() {  

        var student =  
            new GlideRecord(TABLE_STUDENT);  

        if (!student.isValid()) {  
            return null;  
        }  


        if (  
            student.isValidField('user')  
        ) {  

            student =  
                new GlideRecord(TABLE_STUDENT);  

            student.addQuery(  
                'user',  
                CURRENT_USER  
            );  

            student.setLimit(1);  
            student.query();  

            if (student.next()) {  
                return student;  
            }  
        }  


        var email =  
            gs.getUser().getEmail();  

        if (email) {  

            student =  
                new GlideRecord(TABLE_STUDENT);  

            if (  
                student.isValidField('email')  
            ) {  

                student.addQuery(  
                    'email',  
                    email  
                );  

                student.setLimit(1);  
                student.query();  

                if (student.next()) {  
                    return student;  
                }  
            }  
        }  


        var userName =  
            gs.getUserName();  

        if (userName) {  

            student =  
                new GlideRecord(TABLE_STUDENT);  

            if (  
                student.isValidField('user_name')  
            ) {  

                student.addQuery(  
                    'user_name',  
                    userName  
                );  

                student.setLimit(1);  
                student.query();  

                if (student.next()) {  
                    return student;  
                }  
            }  
        }  


        return null;  
    }  


    var currentStudent =  
        getCurrentStudent();  


