    /* ============================================================  
       ELIGIBILITY CHECK  
       ============================================================ */  

    function checkEligibility(  
        drive,  
        student  
    ) {  

        var result = {  

            eligible: true,  

            reason: 'Eligible',  

            cgpa_ok: true,  

            backlog_ok: true,  

            branch_ok: true,  

            mandatory_skills_ok: true,  

            optional_skills_ok: true  
        };  


        if (!student) {  

            result.eligible = false;  

            result.reason =  
                'Student record not found.';  

            return result;  
        }  


        var studentCGPA =  
            parseFloat(  
                value(student, 'cgpa')  
            );  

        var minimumCGPA =  
            parseFloat(  
                value(drive, 'minimum_cgpa')  
            );  


        if (!isNaN(minimumCGPA)) {  

            if (isNaN(studentCGPA)) {  

                result.eligible = false;  
                result.cgpa_ok = false;  

                result.reason =  
                    'Student CGPA is empty or invalid.';  

                return result;  
            }  


            if (  
                studentCGPA <  
                minimumCGPA  
            ) {  

                result.eligible = false;  
                result.cgpa_ok = false;  

                result.reason =  
                    'CGPA requirement not satisfied.';  

                return result;  
            }  
        }  


        var studentBacklogs =  
            parseInt(  
                value(student, 'backlogs'),  
                10  
            );  

        var maxBacklogs =  
            parseInt(  
                value(drive, 'max_backlogs'),  
                10  
            );  


        if (!isNaN(maxBacklogs)) {  

            if (isNaN(studentBacklogs)) {  

                result.eligible = false;  
                result.backlog_ok = false;  

                result.reason =  
                    'Student backlog value is empty or invalid.';  

                return result;  
            }  


            if (  
                studentBacklogs >  
                maxBacklogs  
            ) {  

                result.eligible = false;  
                result.backlog_ok = false;  

                result.reason =  
                    'Maximum backlog requirement not satisfied.';  

                return result;  
            }  
        }  


        var eligibleBranches =  
            splitValues(  
                safeValue(  
                    drive,  
                    'eligible_branches'  
                )  
            );  

        var studentBranch =  
            safeValue(  
                student,  
                'branch'  
            )  
            .toString()  
            .trim();  


        if (  
            eligibleBranches.length > 0  
        ) {  

            if (!studentBranch) {  

                result.eligible = false;  
                result.branch_ok = false;  

                result.reason =  
                    'Student branch is empty.';  

                return result;  
            }  


            var branchMatch = false;  


            for (  
                var b = 0;  
                b < eligibleBranches.length;  
                b++  
            ) {  

                if (  
                    branchMatches(  
                        studentBranch,  
                        eligibleBranches[b]  
                    )  
                ) {  

                    branchMatch = true;  
                    break;  
                }  
            }  


            if (!branchMatch) {  

                result.eligible = false;  
                result.branch_ok = false;  

                result.reason =  
                    'Student branch is not eligible for this drive.';  

                return result;  
            }  
        }  


        var studentSkills =  
            splitValues(  
                safeValue(  
                    student,  
                    'skills'  
                )  
            );  


        var mandatorySkills =  
            splitValues(  
                safeValue(  
                    drive,  
                    'mandatory_skills'  
                )  
            );  


        for (  
            var m = 0;  
            m < mandatorySkills.length;  
            m++  
        ) {  

            var mandatorySkill =  
                mandatorySkills[m];  

            var mandatoryFound = false;  


            for (  
                var s = 0;  
                s < studentSkills.length;  
                s++  
            ) {  

                if (  
                    eligibilityValueMatches(  
                        studentSkills[s],  
                        mandatorySkill  
                    )  
                ) {  

                    mandatoryFound = true;  
                    break;  
                }  
            }  


            if (!mandatoryFound) {  

                result.eligible = false;  
                result.mandatory_skills_ok = false;  

                result.reason =  
                    'Mandatory skill not satisfied: ' +  
                    mandatorySkill;  

                return result;  
            }  
        }  


        var optionalSkills =  
            splitValues(  
                safeValue(  
                    drive,  
                    'skills'  
                )  
            );  


        var minimumOptional =  
            parseInt(  
                value(  
                    drive,  
                    'minimum_optional_skills'  
                ),  
                10  
            );  


        if (  
            !isNaN(minimumOptional) &&  
            minimumOptional > 0 &&  
            optionalSkills.length > 0  
        ) {  

            var optionalMatches = 0;  


            for (  
                var o = 0;  
                o < optionalSkills.length;  
                o++  
            ) {  

                var optionalFound = false;  


                for (  
                    var ss = 0;  
                    ss < studentSkills.length;  
                    ss++  
                ) {  

                    if (  
                        eligibilityValueMatches(  
                            studentSkills[ss],  
                            optionalSkills[o]  
                        )  
                    ) {  

                        optionalFound = true;  
                        break;  
                    }  
                }  


                if (optionalFound) {  
                    optionalMatches++;  
                }  
            }  


            if (  
                optionalMatches <  
                minimumOptional  
            ) {  

                result.eligible = false;  
                result.optional_skills_ok = false;  

                result.reason =  
                    'Minimum optional skills requirement not satisfied.';  

                return result;  
            }  
        }  


        return result;  
    }  


    /* ============================================================  
       EXISTING APPLICATION  
       ============================================================ */  

    function getStudentApplication(  
        driveSysId  
    ) {  

        if (!currentStudent) {  
            return null;  
        }  

        var app =  
            new GlideRecord(  
                TABLE_APPLICATION  
            );  

        if (!app.isValid()) {  
            return null;  
        }  

        if (  
            !app.isValidField('drive') ||  
            !app.isValidField('student')  
        ) {  
            return null;  
        }  

        app.addQuery(  
            'drive',  
            driveSysId  
        );  

        app.addQuery(  
            'student',  
            currentStudent.getUniqueValue()  
        );  

        app.setLimit(1);  
        app.query();  

        if (app.next()) {  
            return app;  
        }  

        return null;  
    }  


    /* ============================================================  
       INTERVIEWER ASSIGNED DRIVES  
       ============================================================ */  

    function getInterviewerDriveIds() {  

        var ids = {};  

        var currentUser =  
            gs.getUserID();  

        var currentUserName =  
            gs.getUserName();  

        var currentUserDisplay =  
            gs.getUserDisplayName();  


        var driveCheck =  
            new GlideRecord(  
                TABLE_DRIVE  
            );  


        if (  
            !driveCheck.isValid()  
        ) {  

            data.debug_interviewer  
                .interview_query_error =  
                'Placement Drive table is invalid: ' +  
                TABLE_DRIVE;  

            return ids;  
        }  


        var driveCompanyExists =  
            driveCheck.isValidField(  
                'company'  
            );  

        var driveInterviewerExists =  
            driveCheck.isValidField(  
                'interviewer'  
            );  

        data.debug_interviewer  
            .placement_drive_company_field_exists =  
            driveCompanyExists;  

        data.debug_interviewer  
            .placement_drive_interviewer_field_exists =  
            driveInterviewerExists;  


        var companyCheck =  
            new GlideRecord(  
                TABLE_COMPANY  
            );  

        if (  
            companyCheck.isValid()  
        ) {  

            data.debug_interviewer  
                .company_hr_user_field_exists =  
                companyCheck.isValidField(  
                    'hr_user'  
                );  
        }  


        /* ========================================================  
           DIRECT INTERVIEWER  
           ======================================================== */  

        if (  
            driveInterviewerExists  
        ) {  

            var directDriveGR =  
                new GlideRecord(  
                    TABLE_DRIVE  
                );  

            directDriveGR.addQuery(  
                'interviewer',  
                currentUser  
            );  

            directDriveGR.query();  

            while (  
                directDriveGR.next()  
            ) {  

                var directId =  
                    directDriveGR.getUniqueValue();  

                if (directId) {  

                    ids[directId] = true;  

                    if (  
                        data.debug_interviewer  
                            .assigned_drive_details  
                            .length < 50  
                    ) {  

                        data.debug_interviewer  
                            .assigned_drive_details  
                            .push({  

                                source:  
                                    'Placement Drive.interviewer',  

                                drive_sys_id:  
                                    directId,  

                                drive_name:  
                                    displayValue(  
                                        directDriveGR,  
                                        'drive_name'  
                                    ),  

                                company:  
                                    displayValue(  
                                        directDriveGR,  
                                        'company'  
                                    ),  

                                hr_user:  
                                    '',  

                                matches_current_user:  
                                    true  
                            });  
                    }  
                }  
            }  
        }  


        /* ========================================================  
           Placement Drive.company → Company.hr_user  
           ======================================================== */  

        if (  
            driveCompanyExists  
        ) {  

            var allDrives =  
                new GlideRecord(  
                    TABLE_DRIVE  
                );  

            allDrives.query();  


            while (  
                allDrives.next()  
            ) {  

                var driveId =  
                    allDrives.getUniqueValue();  

                var companyId =  
                    value(  
                        allDrives,  
                        'company'  
                    );  


                if (!companyId) {  
                    continue;  
                }  


                data.debug_interviewer  
                    .company_record_count++;  


                var company =  
                    new GlideRecord(  
                        TABLE_COMPANY  
                    );  

                if (  
                    !company.get(  
                        companyId  
                    )  
                ) {  
                    continue;  
                }  


                if (  
                    !company.isValidField(  
                        'hr_user'  
                    )  
                ) {  
                    continue;  
                }  


                var hrUserRaw =  
                    value(  
                        company,  
                        'hr_user'  
                    );  

                var hrUserDisplay =  
                    displayValue(  
                        company,  
                        'hr_user'  
                    );  


                var matchesCurrentUser =  
                    false;  


                if (  
                    hrUserRaw ===  
                    currentUser  
                ) {  

                    matchesCurrentUser = true;  
                }  

                if (  
                    normalizeText(hrUserRaw) ===  
                    normalizeText(currentUserName)  
                ) {  

                    matchesCurrentUser = true;  
                }  

                if (  
                    normalizeText(hrUserRaw) ===  
                    normalizeText(currentUserDisplay)  
                ) {  

                    matchesCurrentUser = true;  
                }  

                if (  
                    normalizeText(hrUserDisplay) ===  
                    normalizeText(currentUserName)  
                ) {  

                    matchesCurrentUser = true;  
                }  

                if (  
                    normalizeText(hrUserDisplay) ===  
                    normalizeText(currentUserDisplay)  
                ) {  

                    matchesCurrentUser = true;  
                }  


                if (  
                    data.debug_interviewer  
                        .assigned_drive_details  
                        .length < 50  
                ) {  

                    data.debug_interviewer  
                        .assigned_drive_details  
                        .push({  

                            source:  
                                'Placement Drive.company → Company.hr_user',  

                            drive_sys_id:  
                                driveId,  

                            drive_name:  
                                displayValue(  
                                    allDrives,  
                                    'drive_name'  
                                ),  

                            company:  
                                displayValue(  
                                    allDrives,  
                                    'company'  
                                ),  

                            company_sys_id:  
                                companyId,  

                            hr_user_raw:  
                                hrUserRaw,  

                            hr_user_display:  
                                hrUserDisplay,  

                            current_user:  
                                currentUser,  

                            current_user_name:  
                                currentUserName,  

                            current_user_display:  
                                currentUserDisplay,  

                            matches_current_user:  
                                matchesCurrentUser  
                        });  
                }  


                if (  
                    matchesCurrentUser  
                ) {  

                    data.debug_interviewer  
                        .matching_company_count++;  

                    ids[driveId] = true;  
                }  
            }  
        }  


        /* ========================================================  
           INTERVIEW TABLE DEBUG  
           ======================================================== */  

        var interviewCheck =  
            new GlideRecord(  
                TABLE_INTERVIEW  
            );  


        data.debug_interviewer  
            .interview_table_valid =  
            interviewCheck.isValid();  


        if (  
            interviewCheck.isValid()  
        ) {  

            try {  

                var interviewAggregate =  
                    new GlideAggregate(  
                        TABLE_INTERVIEW  
                    );  

                interviewAggregate.addAggregate(  
                    'COUNT'  
                );  

                interviewAggregate.query();  

                if (  
                    interviewAggregate.next()  
                ) {  

                    data.debug_interviewer  
                        .interview_table_record_count =  
                        parseInt(  
                            interviewAggregate  
                                .getAggregate('COUNT'),  
                            10  
                        );  
                }  

            } catch (e) {  

                data.debug_interviewer  
                    .interview_query_error =  
                    e.toString();  
            }  
        }  


        /* ========================================================  
           FINAL ASSIGNED DRIVE LIST  
           ======================================================== */  

        var result = [];  

        for (  
            var id in ids  
        ) {  

            if (  
                ids.hasOwnProperty(id)  
            ) {  

                result.push(id);  
            }  
        }  


        data.debug_interviewer  
            .assigned_drive_count =  
            result.length;  


        data.debug_interviewer  
            .assigned_drive_ids =  
            result;  


        return ids;  
    }  


    /* ============================================================  
       APPLICATION STATISTICS  
       ============================================================ */  

    function getDriveStatistics(  
        driveSysId  
    ) {  

        var result = {  

            total_applications: 0,  

            applied_count: 0,  

            round1_count: 0,  

            round2_count: 0,  

            round3_count: 0,  

            selected_count: 0,  

            rejected_count: 0,  

            applications: []  
        };  


        var app =  
            new GlideRecord(  
                TABLE_APPLICATION  
            );  


        if (!app.isValid()) {  
            return result;  
        }  


        if (  
            !app.isValidField('drive')  
        ) {  
            return result;  
        }  


        app.addQuery(  
            'drive',  
            driveSysId  
        );  

        app.query();  


        while (  
            app.next()  
        ) {  

            result.total_applications++;  


            var status =  
                normalizeText(  
                    value(  
                        app,  
                        'status'  
                    )  
                );  


            if (  
                status === 'applied'  
            ) {  

                result.applied_count++;  
            }  


            if (  
                containsIgnoreCase(  
                    status,  
                    'selected'  
                )  
            ) {  

                result.selected_count++;  
            }  


            if (  
                containsIgnoreCase(  
                    status,  
                    'rejected'  
                )  
            ) {  

                result.rejected_count++;  
            }  


            var latestRound = '';  


            var interview =  
                new GlideRecord(  
                    TABLE_INTERVIEW  
                );  


            if (  
                interview.isValid() &&  
                interview.isValidField(  
                    'single_student_application'  
                )  
            ) {  

                interview.addQuery(  
                    'single_student_application',  
                    app.getUniqueValue()  
                );  


                if (  
                    interview.isValidField(  
                        'interview_date'  
                    )  
                ) {  

                    interview.orderByDesc(  
                        'interview_date'  
                    );  
                }  


                interview.setLimit(1);  
                interview.query();  


                if (  
                    interview.next()  
                ) {  

                    latestRound =  
                        displayValue(  
                            interview,  
                            'round_name'  
                        );  
                }  
            }  


            result.applications.push({  

                sys_id:  
                    app.getUniqueValue(),  

                application_number:  
                    displayValue(  
                        app,  
                        'application_number'  
                    ),  

                student_name:  
                    displayValue(  
                        app,  
                        'student'  
                    ),  

                register_number:  
                    displayValue(  
                        app,  
                        'student.register_number'  
                    ),  

                branch:  
                    displayValue(  
                        app,  
                        'student.branch'  
                    ),  

                cgpa:  
                    displayValue(  
                        app,  
                        'student.cgpa'  
                    ),  

                status:  
                    displayValue(  
                        app,  
                        'status'  
                    ),  

                current_round:  
                    latestRound  
            });  
        }  


        /* ========================================================  
           INTERVIEW ROUND COUNTS  
           ======================================================== */  

        var interviewGR =  
            new GlideRecord(  
                TABLE_INTERVIEW  
            );  


        if (  
            interviewGR.isValid() &&  
            interviewGR.isValidField(  
                'drive'  
            )  
        ) {  

            interviewGR.addQuery(  
                'drive',  
                driveSysId  
            );  

            interviewGR.query();  


            while (  
                interviewGR.next()  
            ) {  

                var round =  
                    displayValue(  
                        interviewGR,  
                        'round_name'  
                    )  
                    .toString()  
                    .toLowerCase();  


                if (  
                    containsIgnoreCase(  
                        round,  
                        '1'  
                    )  
                ) {  

                    result.round1_count++;  

                } else if (  
                    containsIgnoreCase(  
                        round,  
                        '2'  
                    )  
                ) {  

                    result.round2_count++;  

                } else if (  
                    containsIgnoreCase(  
                        round,  
                        '3'  
                    )  
                ) {  

                    result.round3_count++;  
                }  
            }  
        }  


        return result;  
    }  


    /* ============================================================  
       COMPANY  
       ============================================================ */  

    function getCompany(  
        companySysId  
    ) {  

        var result = {  

            sys_id: '',  

            company_name: '',  

            location: '',  

            description: '',  

            website: '',  

            hr_user: '',  

            allow_branches: '',  

            skills: '',  

            bond: ''  
        };  


        if (!companySysId) {  
            return result;  
        }  


        var company =  
            new GlideRecord(  
                TABLE_COMPANY  
            );  


        if (  
            !company.get(  
                companySysId  
            )  
        ) {  

            return result;  
        }  


        result.sys_id =  
            company.getUniqueValue();  


        result.company_name =  
            displayValue(  
                company,  
                'company_name'  
            );  


        result.location =  
            displayValue(  
                company,  
                'location'  
            );  


        result.description =  
            displayValue(  
                company,  
                'description'  
            );  


        result.website =  
            displayValue(  
                company,  
                'website'  
            );  


        result.hr_user =  
            displayValue(  
                company,  
                'hr_user'  
            );  


        result.allow_branches =  
            displayValue(  
                company,  
                'allow_branches'  
            );  


        result.skills =  
            displayValue(  
                company,  
                'skills'  
            );  


        result.bond =  
            displayValue(  
                company,  
                'bond'  
            );  


        return result;  
    }  


    /* ============================================================  
       BUILD DRIVE  
       ============================================================ */  

    function buildDrive(  
        drive  
    ) {  

        var company =  
            getCompany(  
                value(  
                    drive,  
                    'company'  
                )  
            );  


        var statusInfo =  
            getDriveStatusInfo(drive);  


        var driveObject = {  

            sys_id:  
                drive.getUniqueValue(),  

            drive_name:  
                displayValue(  
                    drive,  
                    'drive_name'  
                ),  

            company:  
                value(  
                    drive,  
                    'company'  
                ),  

            company_name:  
                company.company_name,  

            company_location:  
                company.location,  

            company_description:  
                company.description,  

            company_website:  
                company.website,  

            hr_user:  
                company.hr_user,  

            status:  
                statusInfo.display,  

            status_raw:  
                statusInfo.raw,  

            status_normalized:  
                statusInfo.normalized_display,  

            is_open:  
                statusInfo.is_open,  

            registration_deadline:  
                displayValue(  
                    drive,  
                    'registration_deadline'  
                ),  

            minimum_cgpa:  
                displayValue(  
                    drive,  
                    'minimum_cgpa'  
                ),  

            max_backlogs:  
                displayValue(  
                    drive,  
                    'max_backlogs'  
                ),  

            drive_date:  
                displayValue(  
                    drive,  
                    'drive_date'  
                ),  

            eligible_branches:  
                displayValue(  
                    drive,  
                    'eligible_branches'  
                ),  

            eligibility_count:  
                displayValue(  
                    drive,  
                    'eligibility_count'  
                ),  

            mandatory_skills:  
                displayValue(  
                    drive,  
                    'mandatory_skills'  
                ),  

            minimum_optional_skills:  
                displayValue(  
                    drive,  
                    'minimum_optional_skills'  
                ),  

            job_role:  
                displayValue(  
                    drive,  
                    'job_role'  
                ),  

            skills:  
                displayValue(  
                    drive,  
                    'skills'  
                ),  

            package:  
                displayValue(  
                    drive,  
                    'package'  
                ),  

            skill_list: [],  

            is_eligible: false,  

            eligibility_reason:  
                'Not checked',  

            eligibility_debug: {},  

            has_applied: false,  

            application_sys_id: '',  

            total_applications: 0,  

            applied_count: 0,  

            round1_count: 0,  

            round2_count: 0,  

            round3_count: 0,  

            selected_count: 0,  

            rejected_count: 0,  

            applications: [],  

            can_view: false,  

            can_edit: false,  

            can_apply: false  
        };  


        /* ========================================================  
           COMPANY INITIALS  
           ======================================================== */  

        if (  
            company.company_name  
        ) {  

            var words =  
                company.company_name  
                    .trim()  
                    .split(/\s+/);  


            if (  
                words.length >= 2  
            ) {  

                driveObject.company_initials =  
                    (  
                        words[0].charAt(0) +  
                        words[1].charAt(0)  
                    ).toUpperCase();  

            } else {  

                driveObject.company_initials =  
                    company.company_name  
                        .substring(0, 2)  
                        .toUpperCase();  
            }  

        } else {  

            driveObject.company_initials =  
                'CO';  
        }  


        /* ========================================================  
           SKILLS  
           ======================================================== */  

        driveObject.skill_list =  
            splitValues(  
                driveObject.skills  
            );  


        /* ========================================================  
           ELIGIBILITY  
           ======================================================== */  

        if (  
            currentStudent  
        ) {  

            var eligibilityResult =  
                checkEligibility(  
                    drive,  
                    currentStudent  
                );  


            driveObject.is_eligible =  
                eligibilityResult.eligible;  


            driveObject.eligibility_reason =  
                eligibilityResult.reason;  


            driveObject.eligibility_debug = {  

                cgpa_ok:  
                    eligibilityResult.cgpa_ok,  

                backlog_ok:  
                    eligibilityResult.backlog_ok,  

                branch_ok:  
                    eligibilityResult.branch_ok,  

                mandatory_skills_ok:  
                    eligibilityResult.mandatory_skills_ok,  

                optional_skills_ok:  
                    eligibilityResult.optional_skills_ok  
            };  

        } else {  

            driveObject.is_eligible =  
                false;  

            driveObject.eligibility_reason =  
                'Student record not found.';  
        }  


        /* ========================================================  
           APPLICATION  
           ======================================================== */  

        var existingApplication =  
            getStudentApplication(  
                drive.getUniqueValue()  
            );  


        if (  
            existingApplication  
        ) {  

            driveObject.has_applied =  
                true;  

            driveObject.application_sys_id =  
                existingApplication.getUniqueValue();  
        }  


        /* ========================================================  
           STATISTICS  
           ======================================================== */  

        var stats =  
            getDriveStatistics(  
                drive.getUniqueValue()  
            );  


        driveObject.total_applications =  
            stats.total_applications;  

        driveObject.applied_count =  
            stats.applied_count;  

        driveObject.round1_count =  
            stats.round1_count;  

        driveObject.round2_count =  
            stats.round2_count;  

        driveObject.round3_count =  
            stats.round3_count;  

        driveObject.selected_count =  
            stats.selected_count;  

        driveObject.rejected_count =  
            stats.rejected_count;  

        driveObject.applications =  
            stats.applications;  


        /* ========================================================  
           PERMISSIONS  
           ======================================================== */  

        if (  
            data.is_placement_admin  
        ) {  

            driveObject.can_view = true;  
            driveObject.can_edit = true;  
            driveObject.can_apply = false;  

        }  

        else if (  
            data.is_placement_officer  
        ) {  

            driveObject.can_view = true;  
            driveObject.can_edit = false;  

            driveObject.can_apply =  
                driveObject.is_eligible === true &&  
                driveObject.has_applied === false &&  
                driveObject.is_open === true;  

        }  

        else if (  
            data.is_interviewer  
        ) {  

            driveObject.can_view = true;  
            driveObject.can_edit = true;  
            driveObject.can_apply = false;  

        }  

        else if (  
            data.is_student  
        ) {  

            driveObject.can_view = false;  
            driveObject.can_edit = false;  

            driveObject.can_apply =  
                driveObject.is_eligible === true &&  
                driveObject.has_applied === false &&  
                driveObject.is_open === true;  
        }  


        /* ========================================================  
           FINAL DEBUG  
           ======================================================== */  

        driveObject.permission_debug = {  

            is_student:  
                data.is_student,  

            is_placement_officer:  
                data.is_placement_officer,  

            is_interviewer:  
                data.is_interviewer,  

            is_eligible:  
                driveObject.is_eligible,  

            has_applied:  
                driveObject.has_applied,  

            status:  
                driveObject.status,  

            status_raw:  
                driveObject.status_raw,  

            is_open:  
                driveObject.is_open,  

            can_apply:  
                driveObject.can_apply,  

            eligibility_reason:  
                driveObject.eligibility_reason  
        };  


        return driveObject;  
    }  


    /* ============================================================  
       GET DRIVES  
       ============================================================ */  

    function getDrives() {  

        var drives = [];  

        var drive =  
            new GlideRecord(  
                TABLE_DRIVE  
            );  

        if (  
            !drive.isValid()  
        ) {  
            return drives;  
        }  

        var interviewerDriveIds = {};  

        if (  
            data.is_interviewer  
        ) {  

            interviewerDriveIds =  
                getInterviewerDriveIds();  

            if (  
                Object.keys(  
                    interviewerDriveIds  
                ).length === 0  
            ) {  

                return drives;  
            }  
        }  

        drive.orderByDesc(  
            'drive_date'  
        );  

        drive.query();  

        while (  
            drive.next()  
        ) {  

            var driveId =  
                drive.getUniqueValue();  

            if (  
                data.is_interviewer  
            ) {  

                if (  
                    !interviewerDriveIds[  
                        driveId  
                    ]  
                ) {  
                    continue;  
                }  
            }  

            var driveObject =  
                buildDrive(  
                    drive  
                );  

            if (  
                data.is_student  
            ) {  

                if (  
                    driveObject.is_eligible !== true &&  
                    driveObject.has_applied !== true  
                ) {  

                    continue;  
                }  
            }  

            drives.push(  
                driveObject  
            );  
        }  

        return drives;  
    }  


    /* ============================================================  
       COMPANY LIST  
       ============================================================ */  

    function getCompanies() {  

        var companies = [];  

        if (  
            !data.is_placement_admin &&  
            !data.is_interviewer  
        ) {  

            return companies;  
        }  

        var company =  
            new GlideRecord(  
                TABLE_COMPANY  
            );  

        if (  
            !company.isValid()  
        ) {  
            return companies;  
        }  

        company.orderBy(  
            'company_name'  
        );  

        company.query();  

        while (  
            company.next()  
        ) {  

            companies.push({  

                sys_id:  
                    company.getUniqueValue(),  

                company_name:  
                    displayValue(  
                        company,  
                        'company_name'  
                    )  
            });  
        }  

        return companies;  
    }  


    /* ============================================================  
       BRANCH LIST  
       ============================================================ */  

    function getBranches() {  

        var branches = [];  

        var branchMap = {};  

        var student =  
            new GlideRecord(  
                TABLE_STUDENT  
            );  

        if (  
            !student.isValid()  
        ) {  
            return branches;  
        }  

        student.query();  

        while (  
            student.next()  
        ) {  

            var branch =  
                displayValue(  
                    student,  
                    'branch'  
                );  

            if (  
                branch &&  
                !branchMap[branch]  
            ) {  

                branchMap[branch] = true;  

                branches.push(  
                    branch  
                );  
            }  
        }  

        return branches;  
    }  


    /* ============================================================  
       LOAD DATA  
       ============================================================ */  

    data.drives =  
        getDrives();  

    data.companies =  
        getCompanies();  

    data.branches =  
        getBranches();  


    /* ============================================================  
       SUMMARY  
       ============================================================ */  

    function buildSummary() {  

        var summary = {  

            total_drives:  
                data.drives.length,  

            open_drives: 0,  

            total_applications: 0,  

            total_selected: 0  
        };  

        for (  
            var i = 0;  
            i < data.drives.length;  
            i++  
        ) {  

            var d =  
                data.drives[i];  

            if (  
                d.is_open === true  
            ) {  

                summary.open_drives++;  
            }  

            summary.total_applications +=  
                parseInt(  
                    d.total_applications || 0,  
                    10  
                );  

            summary.total_selected +=  
                parseInt(  
                    d.selected_count || 0,  
                    10  
                );  
        }  

        return summary;  
    }  


    data.summary =  
        buildSummary();  


    /* ============================================================  
       SERVER ACTIONS  
       ============================================================ */  

    if (  
        input &&  
        input.action  
    ) {  


        /* ========================================================  
           GET SINGLE DRIVE  
           ======================================================== */  

        if (  
            input.action ===  
            'get_drive'  
        ) {  

            var requestedDrive =  
                new GlideRecord(  
                    TABLE_DRIVE  
                );  

            if (  
                requestedDrive.get(  
                    input.sys_id  
                )  
            ) {  

                var requestedObject =  
                    buildDrive(  
                        requestedDrive  
                    );  

                var allowed = false;  

                if (  
                    data.is_placement_admin ||  
                    data.is_placement_officer  
                ) {  

                    allowed = true;  
                }  

                if (  
                    data.is_interviewer  
                ) {  

                    var assignedIds =  
                        getInterviewerDriveIds();  

                    allowed =  
                        !!assignedIds[  
                            requestedDrive  
                                .getUniqueValue()  
                        ];  
                }  

                if (  
                    data.is_student  
                ) {  

                    allowed =  
                        requestedObject.is_eligible === true ||  
                        requestedObject.has_applied === true;  
                }  

                if (  
                    allowed  
                ) {  

                    data.selectedDrive =  
                        requestedObject;  

                } else {  

                    data.error =  
                        'You are not allowed to view this placement drive.';  
                }  

            } else {  

                data.error =  
                    'Placement drive not found.';  
            }  
        }  


        /* ========================================================  
           APPLY APPLICATION  
           ROBUST VERSION  
           ======================================================== */  

        if (  
            input.action ===  
            'apply'  
        ) {  

            /* ----------------------------------------------------  
               RESET RESPONSE  
               ---------------------------------------------------- */  

            data.actionSuccess = false;  
            data.application_sys_id = '';  
            data.message = '';  
            data.error = '';  


            /* ----------------------------------------------------  
               APPLY DEBUG  
               ---------------------------------------------------- */  

            data.apply_debug = {  

                action_received: true,  

                current_user:  
                    CURRENT_USER,  

                current_user_name:  
                    CURRENT_USER_NAME,  

                is_student:  
                    data.is_student,  

                is_placement_officer:  
                    data.is_placement_officer,  

                student_found:  
                    !!currentStudent,  

                student_sys_id:  
                    currentStudent  
                        ? currentStudent.getUniqueValue()  
                        : '',  

                drive_sys_id:  
                    input.drive_sys_id  
                        ? input.drive_sys_id.toString()  
                        : '',  

                application_table_valid:  
                    false,  

                student_field_valid:  
                    false,  

                drive_field_valid:  
                    false,  

                status_field_valid:  
                    false,  

                eligibility_field_valid:  
                    false,  

                inserted_id: '',  

                error_stage: ''  
            };  


            /* ----------------------------------------------------  
               ROLE CHECK  
               ---------------------------------------------------- */  

            if (  
                !data.is_student &&  
                !data.is_placement_officer  
            ) {  

                data.apply_debug.error_stage =  
                    'ROLE_CHECK';  

                data.error =  
                    'Only students and placement officers can apply.';  

            }  


            /* ----------------------------------------------------  
               STUDENT CHECK  
               ---------------------------------------------------- */  

            else if (  
                !currentStudent ||  
                !currentStudent.isValidRecord()  
            ) {  

                data.apply_debug.error_stage =  
                    'STUDENT_CHECK';  

                data.error =  
                    'Student record not found for this account.';  

            }  


            /* ----------------------------------------------------  
               DRIVE ID CHECK  
               ---------------------------------------------------- */  

            else if (  
                !input.drive_sys_id ||  
                !input.drive_sys_id.toString().trim()  
            ) {  

                data.apply_debug.error_stage =  
                    'DRIVE_ID_CHECK';  

                data.error =  
                    'Placement drive ID is missing.';  

            }  


            else {  

                /* ------------------------------------------------  
                   LOAD DRIVE  
                   ------------------------------------------------ */  

                var applyDrive =  
                    new GlideRecord(  
                        TABLE_DRIVE  
                    );  


                if (  
                    !applyDrive.isValid()  
                ) {  

                    data.apply_debug.error_stage =  
                        'DRIVE_TABLE_INVALID';  

                    data.error =  
                        'Placement Drive table is invalid: ' +  
                        TABLE_DRIVE;  

                }  


                else if (  
                    !applyDrive.get(  
                        input.drive_sys_id.toString().trim()  
                    )  
                ) {  

                    data.apply_debug.error_stage =  
                        'DRIVE_NOT_FOUND';  

                    data.error =  
                        'Placement drive not found.';  

                }  


                else {  

                    /* --------------------------------------------  
                       STATUS CHECK  
                       -------------------------------------------- */  

                    var applyStatusInfo =  
                        getDriveStatusInfo(  
                            applyDrive  
                        );  


                    if (  
                        !applyStatusInfo.is_open  
                    ) {  

                        data.apply_debug.error_stage =  
                            'DRIVE_NOT_OPEN';  

                        data.error =  
                            'This placement drive is not open for applications.';  

                    }  


                    else {  

                        /* ----------------------------------------  
                           ELIGIBILITY CHECK  
                           ---------------------------------------- */  

                        var applyEligibility =  
                            checkEligibility(  
                                applyDrive,  
                                currentStudent  
                            );  


                        if (  
                            !applyEligibility.eligible  
                        ) {  

                            data.apply_debug.error_stage =  
                                'ELIGIBILITY_FAILED';  

                            data.error =  
                                'You are not eligible for this placement drive. ' +  
                                applyEligibility.reason;  

                        }  


                        else {  

                            /* ------------------------------------  
                               DUPLICATE CHECK  
                               ------------------------------------ */  

                            var duplicate =  
                                getStudentApplication(  
                                    applyDrive.getUniqueValue()  
                                );  


                            if (  
                                duplicate  
                            ) {  

                                data.apply_debug.error_stage =  
                                    'DUPLICATE_APPLICATION';  

                                data.error =  
                                    'You have already applied for this drive.';  

                            }  


                            else {  

                                /* --------------------------------  
                                   APPLICATION TABLE  
                                   -------------------------------- */  

                                var newApplication =  
                                    new GlideRecord(  
                                        TABLE_APPLICATION  
                                    );  


                                data.apply_debug.application_table_valid =  
                                    newApplication.isValid();  


                                data.apply_debug.student_field_valid =  
                                    newApplication.isValidField('student');  


                                data.apply_debug.drive_field_valid =  
                                    newApplication.isValidField('drive');  


                                data.apply_debug.status_field_valid =  
                                    newApplication.isValidField('status');  


                                data.apply_debug.eligibility_field_valid =  
                                    newApplication.isValidField('eligibility_status');  


                                /* --------------------------------  
                                   TABLE VALIDATION  
                                   -------------------------------- */  

                                if (  
                                    !newApplication.isValid()  
                                ) {  

                                    data.apply_debug.error_stage =  
                                        'APPLICATION_TABLE_INVALID';  

                                    data.error =  
                                        'Application table is invalid: ' +  
                                        TABLE_APPLICATION;  

                                }  


                                else if (  
                                    !newApplication.isValidField('student')  
                                ) {  

                                    data.apply_debug.error_stage =  
                                        'STUDENT_FIELD_MISSING';  

                                    data.error =  
                                        'Application table does not contain the student field.';  

                                }  


                                else if (  
                                    !newApplication.isValidField('drive')  
                                ) {  

                                    data.apply_debug.error_stage =  
                                        'DRIVE_FIELD_MISSING';  

                                    data.error =  
                                        'Application table does not contain the drive field.';  

                                }  


                                else {  

                                    /* ----------------------------  
                                       INITIALIZE  
                                       ---------------------------- */  

                                    newApplication.initialize();  


                                    /* ----------------------------  
                                       STUDENT  
                                       ---------------------------- */  

                                    newApplication.setValue(  
                                        'student',  
                                        currentStudent.getUniqueValue()  
                                    );  


                                    /* ----------------------------  
                                       DRIVE  
                                       ---------------------------- */  

                                    newApplication.setValue(  
                                        'drive',  
                                        applyDrive.getUniqueValue()  
                                    );  


                                    /* ----------------------------  
                                       APPLICATION DATE  
                                       ---------------------------- */  

                                    if (  
                                        newApplication.isValidField(  
                                            'application_date'  
                                        )  
                                    ) {  

                                        try {  

                                            newApplication.setValue(  
                                                'application_date',  
                                                gs.nowDateTime()  
                                            );  

                                        } catch (dateException) {  

                                            /*  
                                             * Date field is not  
                                             * allowed to block the  
                                             * application creation.  
                                             */  

                                        }  
                                    }  


                                    /* ----------------------------  
                                       ELIGIBILITY STATUS  
                                       ---------------------------- */  

                                    if (  
                                        newApplication.isValidField(  
                                            'eligibility_status'  
                                        )  
                                    ) {  

                                        setChoiceIfAvailable(  
                                            newApplication,  
                                            TABLE_APPLICATION,  
                                            'eligibility_status',  
                                            'eligible'  
                                        );  
                                    }  


                                    /* ----------------------------  
                                       APPLICATION STATUS  
                                       ---------------------------- */  

                                    if (  
                                        newApplication.isValidField(  
                                            'status'  
                                        )  
                                    ) {  

                                        setChoiceIfAvailable(  
                                            newApplication,  
                                            TABLE_APPLICATION,  
                                            'status',  
                                            'applied'  
                                        );  
                                    }  


                                    /* ----------------------------  
                                       INSERT APPLICATION  
                                       ---------------------------- */  

                                    var newId = '';  

                                    try {  

                                        newId =  
                                            newApplication.insert();  

                                    } catch (insertException) {  

                                        data.apply_debug.error_stage =  
                                            'INSERT_EXCEPTION';  

                                        data.error =  
                                            'Unable to create application. ' +  
                                            insertException.toString();  
                                    }  


                                    /* ----------------------------  
                                       SUCCESS  
                                       ---------------------------- */  

                                    if (  
                                        newId  
                                    ) {  

                                        data.apply_debug.inserted_id =  
                                            newId.toString();  


                                        /*  
                                         * Verify the record after  
                                         * insert.  
                                         */  

                                        var verifyApplication =  
                                            new GlideRecord(  
                                                TABLE_APPLICATION  
                                            );  


                                        if (  
                                            verifyApplication.get(  
                                                newId.toString()  
                                            )  
                                        ) {  

                                            data.actionSuccess =  
                                                true;  

                                            data.application_sys_id =  
                                                newId.toString();  

                                            data.message =  
                                                'Application submitted successfully.';  

                                            data.apply_debug.error_stage =  
                                                'SUCCESS';  

                                        }  

                                        else {  

                                            data.apply_debug.error_stage =  
                                                'VERIFY_FAILED';  

                                            data.error =  
                                                'Application insert returned an ID, but the application record could not be verified.';  
                                        }  

                                    }  


                                    /* ----------------------------  
                                       INSERT FAILED  
                                       ---------------------------- */  

                                    else if (  
                                        !data.error  
                                    ) {  

                                        var applicationError = '';  


                                        try {  

                                            applicationError =  
                                                newApplication  
                                                    .getLastErrorMessage();  

                                        } catch (applicationErrorException) {  

                                            applicationError =  
                                                applicationErrorException  
                                                    .toString();  
                                        }  


                                        if (  
                                            !applicationError  
                                        ) {  

                                            applicationError =  
                                                'ServiceNow could not insert the application. Check mandatory fields, ACLs, choice values, Business Rules, Data Policies, and application table configuration.';  
                                        }  


                                        data.apply_debug.error_stage =  
                                            'INSERT_FAILED';  

                                        data.error =  
                                            'Unable to create application. ' +  
                                            applicationError;  
                                    }  
                                }  
                            }  
                        }  
                    }  
                }  
            }  
        }  


        /* ========================================================  
           SAVE / UPDATE DRIVE  
           ======================================================== */  

        if (  
            input.action ===  
            'save_drive'  
        ) {  

            data.actionSuccess = false;  
            data.saved_drive_sys_id = '';  
            data.message = '';  
            data.error = '';  


            if (  
                !data.is_placement_admin &&  
                !data.is_interviewer  
            ) {  

                data.error =  
                    'Only Placement Admin and Interviewer can add/edit drives.';  

            }  


            else {  

                var saveDrive =  
                    new GlideRecord(  
                        TABLE_DRIVE  
                    );  

                var driveSysId =  
                    input.sys_id  
                        ? input.sys_id.toString().trim()  
                        : '';  

                var isNew =  
                    !driveSysId;  


                if (  
                    !saveDrive.isValid()  
                ) {  

                    data.error =  
                        'Placement Drive table is invalid: ' +  
                        TABLE_DRIVE;  

                }  


                else if (  
                    isNew  
                ) {  

                    saveDrive.initialize();  

                }  


                else {  

                    if (  
                        !saveDrive.get(  
                            driveSysId  
                        )  
                    ) {  

                        data.error =  
                            'Placement drive not found for update.';  

                    }  

                    else if (  
                        data.is_interviewer &&  
                        !data.is_placement_admin  
                    ) {  

                        var interviewerIds =  
                            getInterviewerDriveIds();  

                        if (  
                            !interviewerIds[  
                                saveDrive  
                                    .getUniqueValue()  
                            ]  
                        ) {  

                            data.error =  
                                'You can edit only drives assigned to you.';  
                        }  
                    }  
                }  


                if (  
                    !data.error  
                ) {  

                    if (  
                        !saveDrive.isValidField(  
                            'drive_name'  
                        )  
                    ) {  

                        data.error =  
                            'Placement Drive table does not contain drive_name.';  

                    }  

                    else if (  
                        !saveDrive.isValidField(  
                            'company'  
                        )  
                    ) {  

                        data.error =  
                            'Placement Drive table does not contain company.';  

                    }  

                    else if (  
                        !saveDrive.isValidField(  
                            'job_role'  
                        )  
                    ) {  

                        data.error =  
                            'Placement Drive table does not contain job_role.';  
                    }  
                }  


                if (  
                    !data.error  
                ) {  

                    if (  
                        !input.drive_name ||  
                        !input.drive_name.toString().trim()  
                    ) {  

                        data.error =  
                            'Drive Name is required.';  

                    }  

                    else if (  
                        !input.company ||  
                        !input.company.toString().trim()  
                    ) {  

                        data.error =  
                            'Company is required.';  

                    }  

                    else if (  
                        !input.job_role ||  
                        !input.job_role.toString().trim()  
                    ) {  

                        data.error =  
                            'Job Role is required.';  
                    }  
                }  


                if (  
                    !data.error  
                ) {  

                    if (  
                        saveDrive.isValidField(  
                            'drive_name'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'drive_name',  
                            input.drive_name  
                                .toString()  
                                .trim()  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'company'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'company',  
                            input.company  
                                .toString()  
                                .trim()  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'status'  
                        )  
                    ) {  

                        var inputStatus =  
                            input.status || 'open';  

                        if (  
                            normalizeText(  
                                inputStatus  
                            ) === 'open'  
                        ) {  

                            saveDrive.setValue(  
                                'status',  
                                'open'  
                            );  

                        } else {  

                            saveDrive.setValue(  
                                'status',  
                                inputStatus  
                            );  
                        }  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'registration_deadline'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'registration_deadline',  
                            input.registration_deadline || ''  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'minimum_cgpa'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'minimum_cgpa',  
                            input.minimum_cgpa || ''  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'max_backlogs'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'max_backlogs',  
                            input.max_backlogs === null ||  
                            input.max_backlogs === undefined ||  
                            input.max_backlogs === ''  
                                ? 0  
                                : input.max_backlogs  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'drive_date'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'drive_date',  
                            input.drive_date || ''  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'eligible_branches'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'eligible_branches',  
                            input.eligible_branches || ''  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'mandatory_skills'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'mandatory_skills',  
                            input.mandatory_skills || ''  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'minimum_optional_skills'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'minimum_optional_skills',  
                            input.minimum_optional_skills === null ||  
                            input.minimum_optional_skills === undefined ||  
                            input.minimum_optional_skills === ''  
                                ? 0  
                                : input.minimum_optional_skills  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'job_role'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'job_role',  
                            input.job_role  
                                .toString()  
                                .trim()  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'skills'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'skills',  
                            input.skills || ''  
                        );  
                    }  


                    if (  
                        saveDrive.isValidField(  
                            'package'  
                        )  
                    ) {  

                        saveDrive.setValue(  
                            'package',  
                            input.package || ''  
                        );  
                    }  
                }  


                if (  
                    !data.error  
                ) {  

                    var savedId =  
                        isNew  
                            ? saveDrive.insert()  
                            : saveDrive.update();  


                    if (  
                        savedId  
                    ) {  

                        data.actionSuccess =  
                            true;  

                        data.saved_drive_sys_id =  
                            savedId.toString();  

                        data.message =  
                            isNew  
                                ? 'Placement drive created successfully.'  
                                : 'Placement drive updated successfully.';  

                    } else {  

                        var saveError = '';  

                        try {  

                            saveError =  
                                saveDrive  
                                    .getLastErrorMessage();  

                        } catch (saveErrorException) {  

                            saveError =  
                                saveErrorException  
                                    .toString();  
                        }  

                        if (  
                            !saveError  
                        ) {  

                            saveError =  
                                isNew  
                                    ? 'ServiceNow could not create the placement drive. Check mandatory fields, ACLs, choice values, Business Rules, and Data Policies.'  
                                    : 'ServiceNow could not update the placement drive. Check mandatory fields, ACLs, choice values, Business Rules, and Data Policies.';  
                        }  

                        data.error =  
                            saveError;  
                    }  
                }  
            }  
        }  


        /* ========================================================  
           REFRESH  
           ======================================================== */  

        if (  
            input.action ===  
            'refresh'  
        ) {  

            data.drives =  
                getDrives();  

            data.summary =  
                buildSummary();  

            data.companies =  
                getCompanies();  

            data.branches =  
                getBranches();  
        }  
    }  

})();
